{"command": "python3 - <<'PY'
import json
D=json.load(open('/workspace/contracts/openapi.contract.json'))
def shape(s):
 if '$ref' in s:return s['$ref'].split('/')[-1]
 if 'allOf' in s:return ' & '.join(shape(x) for x in s['allOf'])
 if 'oneOf' in s:return ' | '.join(shape(x) for x in s['oneOf'])
 t=s.get('type','?')
 if t=='array': return '['+shape(s.get('items',{}))+']'
 if t=='object':
  req=set(s.get('required',[])); ps=s.get('properties',{})
  return '{'+', '.join(k+('!' if k in req else '')+':'+shape(v) for k,v in ps.items())+'}'
 if 'enum'in s:return t+'('+('|'.join(map(str,s['enum'])))+')'
 return t
for p,ms in D['paths'].items():
 for m,o in ms.items():
  if m not in ['get','post']:continue
  req=o.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema')
  succ=[(c,r) for c,r in o['responses'].items() if c.startswith('2')]
  print(f"\n{o['operationId']} {m.upper()} {p}")
  print(' IN ',shape(req) if req else '-')
  for c,r in succ:
   ct=r.get('content',{})
   sch=(ct.get('application/json') or ct.get('text/event-stream') or {}).get('schema',{})
   print(' OUT',c,shape(sch), 'ctype',','.join(ct))
PY", "security_risk": "LOW", "summary": "Summarize operation inputs and success outputs compactly"}

