package main

import (
	"context"
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"math"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"

	_ "github.com/lib/pq"
	"github.com/lib/pq"
	"golang.org/x/crypto/bcrypt"
)

type App struct {
	db *sql.DB
	staticDir string
}

type Session struct {
	Token, UserID, Username, FullName, ActiveRole, AssignedLocationID string
	Roles, Qualifications pq.StringArray
	Active bool
}

type apiError struct { Status int; Code, Message string }
func (e *apiError) Error() string { return e.Message }

func main() {
	dsn := os.Getenv("DATABASE_URL")
	if dsn == "" { log.Fatal("DATABASE_URL is required") }
	db, err := sql.Open("postgres", dsn)
	if err != nil { log.Fatal(err) }
	db.SetMaxOpenConns(20)
	db.SetMaxIdleConns(5)
	db.SetConnMaxLifetime(30 * time.Minute)
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second); defer cancel()
	if err := db.PingContext(ctx); err != nil { log.Fatalf("database unavailable: %v", err) }
	a := &App{db: db, staticDir: "/workspace/frontend/dist"}
	if err := a.ensureInitialAdmin(ctx); err != nil { log.Fatalf("initial administrator: %v", err) }
	mux := http.NewServeMux()
	mux.HandleFunc("/ready", a.ready)
	mux.HandleFunc("/api/", a.api)
	mux.HandleFunc("/maps/", a.mapAsset)
	mux.HandleFunc("/", a.frontend)
	srv := &http.Server{Addr: "127.0.0.1:8080", Handler: securityHeaders(mux), ReadHeaderTimeout: 10*time.Second, ReadTimeout: 30*time.Second, WriteTimeout: 45*time.Second, IdleTimeout: 90*time.Second}
	log.Printf("LabLogix listening on http://127.0.0.1:8080")
	log.Fatal(srv.ListenAndServe())
}

func securityHeaders(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("X-Content-Type-Options", "nosniff")
		w.Header().Set("X-Frame-Options", "DENY")
		w.Header().Set("Referrer-Policy", "no-referrer")
		w.Header().Set("Content-Security-Policy", "default-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; worker-src 'self' blob:; connect-src 'self'; font-src 'self'")
		next.ServeHTTP(w,r)
	})
}

func (a *App) ready(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet { fail(w,405,"method_not_allowed","method not allowed"); return }
	ctx,cancel:=context.WithTimeout(r.Context(),2*time.Second); defer cancel()
	if err:=a.db.PingContext(ctx); err!=nil { writeJSON(w,503,map[string]any{"status":"starting"}); return }
	writeJSON(w,200,map[string]any{"status":"ready"})
}

func (a *App) api(w http.ResponseWriter, r *http.Request) {
	if r.Method == http.MethodOptions { w.WriteHeader(204); return }
	path := r.URL.Path
	if path == "/api/authenticate-user" { if r.Method!=http.MethodPost { fail(w,405,"method_not_allowed","method not allowed"); return }; a.authenticate(w,r); return }
	s, err := a.session(r)
	if err != nil { fail(w,401,"unauthorized","authentication required"); return }
	if path == "/api/select-active-role" { a.selectRole(w,r,s); return }
	if path == "/api/ui/bootstrap" { a.uiBootstrap(w,r,s); return }
	if path == "/api/events" { a.events(w,r,s); return }
	if strings.HasPrefix(path,"/api/read-sample-state/") { a.readSampleState(w,r,s,strings.TrimPrefix(path,"/api/read-sample-state/")); return }
	if strings.HasPrefix(path,"/api/read-user/") { a.readUser(w,r,s,strings.TrimPrefix(path,"/api/read-user/")); return }
	if s.ActiveRole == "" { fail(w,409,"role_not_selected","select an active role"); return }
	h := map[string]func(http.ResponseWriter,*http.Request,*Session){
		"/api/check-serviceability": a.checkServiceability,
		"/api/create-collection-request": a.createCollectionRequest,
		"/api/ingest-presealed-sample": a.ingestPresealed,
		"/api/list-role-work": a.listRoleWork,
		"/api/read-sample-lifecycle": a.readSampleLifecycle,
		"/api/read-journey-plan": a.readJourneyPlan,
		"/api/read-operations-state": a.readOperationsState,
		"/api/read-serviceability-snapshot": a.readServiceabilitySnapshot,
		"/api/search-audit-trail": a.searchAudit,
		"/api/accept-assignment": a.acceptAssignment,
		"/api/decline-assignment": a.declineAssignment,
		"/api/collect-and-seal-sample": a.collectSeal,
		"/api/update-assignment-progress": a.updateProgress,
		"/api/record-worker-location": a.recordWorkerLocation,
		"/api/initiate-handoff": a.initiateHandoff,
		"/api/confirm-handoff": a.confirmHandoff,
		"/api/record-handling-checkpoint": a.handlingCheckpoint,
		"/api/confirm-laboratory-receipt": a.labReceipt,
		"/api/record-laboratory-exception": a.labException,
		"/api/configure-capacity": a.configureCapacity,
		"/api/create-user": a.createUser,
		"/api/update-user-access": a.updateUserAccess,
		"/api/create-sample-type": a.createSampleType,
		"/api/update-sample-type": a.updateSampleType,
		"/api/create-location": a.createLocation,
		"/api/update-location": a.updateLocation,
		"/api/set-location-status": a.setLocationStatus,
		"/api/set-location-function-status": a.setLocationFunctionStatus,
		"/api/create-connection": a.createConnection,
		"/api/set-connection-status": a.setConnectionStatus,
		"/api/configure-laboratory-acceptance": a.configureLabAcceptance,
		"/api/set-worker-availability": a.setWorkerAvailability,
		"/api/cancel-journey": a.cancelJourney,
		"/api/reroute-journey": a.rerouteJourney,
		"/api/report-disruption": a.reportDisruption,
		"/api/edit-active-plan": a.editPlan,
		"/api/split-journey": a.splitJourney,
		"/api/merge-journeys": a.mergeJourneys,
	}
	fn, ok := h[path]
	if !ok { fail(w,404,"not_found","operation not found"); return }
	if r.Method != http.MethodPost { fail(w,405,"method_not_allowed","method not allowed"); return }
	fn(w,r,s)
}

func (a *App) ensureInitialAdmin(ctx context.Context) error {
	var count int
	if err:=a.db.QueryRowContext(ctx,`SELECT count(*) FROM lablogix.users`).Scan(&count); err!=nil{return err}
	if count>0{return nil}
	username,password:=os.Getenv("ADMIN_USERNAME"),os.Getenv("ADMIN_PASSWORD")
	if username==""||password=="" { return errors.New("ADMIN_USERNAME and ADMIN_PASSWORD are required when no users exist") }
	hash,err:=bcrypt.GenerateFromPassword([]byte(password),bcrypt.DefaultCost); if err!=nil{return err}
	id:=uuid()
	_,err=a.db.ExecContext(ctx,`INSERT INTO lablogix.users(id,username,password_hash,full_name,roles) VALUES($1,$2,$3,$4,$5)`,id,username,string(hash),"System Administrator",pq.Array([]string{"administrator"}))
	return err
}

func (a *App) session(r *http.Request) (*Session,error) {
	h:=r.Header.Get("Authorization")
	if !strings.HasPrefix(h,"Bearer "){return nil,errors.New("missing bearer")}
	t:=strings.TrimSpace(strings.TrimPrefix(h,"Bearer "))
	s:=&Session{Token:t}
	err:=a.db.QueryRowContext(r.Context(),`SELECT s.user_id,u.username,COALESCE(u.full_name,''),s.active_role,u.roles,u.qualifications,u.active,COALESCE(u.assigned_location_id::text,'') FROM lablogix.sessions s JOIN lablogix.users u ON u.id=s.user_id WHERE s.token=$1 AND s.expires_at>now()`,t).Scan(&s.UserID,&s.Username,&s.FullName,&s.ActiveRole,&s.Roles,&s.Qualifications,&s.Active,&s.AssignedLocationID)
	if err!=nil||!s.Active{return nil,errors.New("invalid session")}
	return s,nil
}

func (s *Session) hasRole(roles ...string) bool {
	for _,r:=range roles { if s.ActiveRole==r || (s.ActiveRole=="administrator" && r=="dispatcher") { return true } }
	return false
}

func requireRole(w http.ResponseWriter, s *Session, roles ...string) bool {
	if s.hasRole(roles...){return true}
	fail(w,403,"forbidden","the active role cannot perform this action"); return false
}

func decode(r *http.Request, dst any) error {
	d:=json.NewDecoder(http.MaxBytesReader(nil,r.Body,1<<20)); d.DisallowUnknownFields()
	if err:=d.Decode(dst);err!=nil{return &apiError{400,"invalid_json","invalid request body"}}
	if d.Decode(&struct{}{}) != ioEOF{return &apiError{400,"invalid_json","request body must contain one JSON object"}}
	return nil
}

var ioEOF = func() error { var v any; return json.NewDecoder(strings.NewReader("")).Decode(&v) }()

func writeJSON(w http.ResponseWriter, status int, v any) { w.Header().Set("Content-Type","application/json"); w.WriteHeader(status); _=json.NewEncoder(w).Encode(v) }
func data(w http.ResponseWriter,status int,v any){writeJSON(w,status,map[string]any{"data":v})}
func fail(w http.ResponseWriter,status int,code,msg string){writeJSON(w,status,map[string]any{"error":msg,"code":code})}
func handleErr(w http.ResponseWriter,err error){var ae *apiError;if errors.As(err,&ae){fail(w,ae.Status,ae.Code,ae.Message)}else{log.Printf("request error: %v",err);fail(w,500,"internal_error","internal server error")}}

func uuid() string { b:=make([]byte,16); _,_=rand.Read(b); b[6]=(b[6]&0x0f)|0x40; b[8]=(b[8]&0x3f)|0x80; x:=hex.EncodeToString(b); return x[0:8]+"-"+x[8:12]+"-"+x[12:16]+"-"+x[16:20]+"-"+x[20:32] }
func token() string { b:=make([]byte,32); _,_=rand.Read(b); return hex.EncodeToString(b) }
func parseTime(v string)(time.Time,error){t,e:=time.Parse(time.RFC3339,v);if e!=nil{return t,&apiError{400,"invalid_time","time must be RFC3339"}};return t,nil}
func timeText(t time.Time)string{return t.UTC().Format(time.RFC3339)}
func contains(xs []string,x string)bool{for _,v:=range xs{if v==x{return true}};return false}
func nullable(v string) any { if v=="" { return nil }; return v }
func jsonBytes(v any) []byte { b,_:=json.Marshal(v); return b }
func haversine(lat1,lon1,lat2,lon2 float64)float64{const R=6371;dlat:=(lat2-lat1)*math.Pi/180;dlon:=(lon2-lon1)*math.Pi/180;a:=math.Sin(dlat/2)*math.Sin(dlat/2)+math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*math.Sin(dlon/2)*math.Sin(dlon/2);return 2*R*math.Atan2(math.Sqrt(a),math.Sqrt(1-a))}

func (a *App) audit(ctx context.Context,s *Session,action,entityType,entityID string,success bool,details any){actor,role:="system","system";if s!=nil{actor,role=s.UserID,s.ActiveRole};_,_=a.db.ExecContext(ctx,`INSERT INTO lablogix.audit_logs(actor_id,actor_role,action,entity_type,entity_id,success,details) VALUES($1,$2,$3,$4,$5,$6,$7)`,actor,role,action,entityType,entityID,success,jsonBytes(details))}
func (a *App) event(ctx context.Context,eventType,entityType,entityID string,payload any){_,_=a.db.ExecContext(ctx,`INSERT INTO lablogix.realtime_events(event_type,entity_type,entity_id,payload) VALUES($1,$2,$3,$4)`,eventType,entityType,entityID,jsonBytes(payload))}

func (a *App) frontend(w http.ResponseWriter,r *http.Request){
	if strings.HasPrefix(r.URL.Path,"/api/")||r.URL.Path=="/ready"{http.NotFound(w,r);return}
	p:=filepath.Join(a.staticDir,filepath.Clean(r.URL.Path))
	if st,err:=os.Stat(p);err==nil&&!st.IsDir(){http.ServeFile(w,r,p);return}
	http.ServeFile(w,r,filepath.Join(a.staticDir,"index.html"))
}
func (a *App) mapAsset(w http.ResponseWriter,r *http.Request){if r.URL.Path!="/maps/bangalore.pmtiles"{http.NotFound(w,r);return};w.Header().Set("Content-Type","application/vnd.pmtiles");http.ServeFile(w,r,"/workspace/public/maps/bangalore.pmtiles")}

func scanJSON(raw []byte)map[string]any{var v map[string]any;_ = json.Unmarshal(raw,&v);return v}
func boolMap(raw []byte)map[string]bool{var v map[string]bool;_ = json.Unmarshal(raw,&v);if v==nil{v=map[string]bool{}};return v}
func asError(code,msg string,status int)error{return &apiError{status,code,msg}}

func (a *App) bumpNetwork(ctx context.Context) { _,_=a.db.ExecContext(ctx,`UPDATE lablogix.network_meta SET revision=revision+1`) }

func (a *App) transaction(ctx context.Context, fn func(*sql.Tx) error) error { tx,e:=a.db.BeginTx(ctx,&sql.TxOptions{Isolation:sql.LevelSerializable});if e!=nil{return e};if e=fn(tx);e!=nil{_ =tx.Rollback();return e};return tx.Commit() }

func fmtID(v any)string{return fmt.Sprint(v)}

