package main

import (
	"database/sql"
	"net/http"
)

type coordinate struct { Latitude float64 `json:"latitude"`; Longitude float64 `json:"longitude"` }
type locationInput struct {LocationID string `json:"locationId"`;Name string `json:"name"`;Coordinate coordinate `json:"coordinate"`;CoverageKm float64 `json:"coverageKm"`;HandlingMinutes int `json:"handlingMinutes"`;Active bool `json:"active"`;Functions []string `json:"functions"`}
func validCoord(c coordinate)bool{return c.Latitude>=-90&&c.Latitude<=90&&c.Longitude>=-180&&c.Longitude<=180}
func functionMap(fs []string)map[string]bool{m:=map[string]bool{"collection_point":false,"transfer_point":false,"hub":false,"laboratory":false};for _,f:=range fs{if _,ok:=m[f];ok{m[f]=true}};return m}
func validFunctions(fs []string)bool{if len(fs)==0{return false};m:=functionMap(fs);n:=0;for _,v:=range m{if v{n++}};return n==len(fs)}
func locationResponse(id,name string,c coordinate,coverage float64,handling int,active bool,fs map[string]bool)map[string]any{return map[string]any{"locationId":id,"name":name,"coordinate":c,"coverageKm":coverage,"handlingMinutes":handling,"active":active,"functions":fs}}

func (a *App) createLocation(w http.ResponseWriter,r *http.Request,s *Session){if !requireRole(w,s,"administrator"){return};var in locationInput;if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if !validCoord(in.Coordinate){fail(w,400,"invalid_coordinate","invalid coordinate");return};if in.CoverageKm==0{in.CoverageKm=5};if in.CoverageKm<=0||in.CoverageKm>5{fail(w,400,"invalid_node_coverage","coverage must be within 5 km");return};if !validFunctions(in.Functions){fail(w,400,"invalid_location_function","at least one valid function is required");return};id:=uuid();fs:=functionMap(in.Functions);err:=a.transaction(r.Context(),func(tx *sql.Tx)error{if _,e:=tx.ExecContext(r.Context(),`INSERT INTO lablogix.locations(id,name,latitude,longitude,coverage_km,handling_minutes,active,functions) VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,id,in.Name,in.Coordinate.Latitude,in.Coordinate.Longitude,in.CoverageKm,in.HandlingMinutes,in.Active,jsonBytes(fs));e!=nil{return e};_,e:=tx.ExecContext(r.Context(),`INSERT INTO lablogix.capacities(resource_id) VALUES($1)`,id);return e});if err!=nil{handleErr(w,err);return};a.bumpNetwork(r.Context());a.audit(r.Context(),s,"create_location","location",id,true,in);data(w,201,locationResponse(id,in.Name,in.Coordinate,in.CoverageKm,in.HandlingMinutes,in.Active,fs))}
func (a *App) updateLocation(w http.ResponseWriter,r *http.Request,s *Session){if !requireRole(w,s,"administrator"){return};var in locationInput;if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if !validCoord(in.Coordinate){fail(w,400,"invalid_coordinate","invalid coordinate");return};if in.CoverageKm==0{in.CoverageKm=5};if in.CoverageKm<=0||in.CoverageKm>5{fail(w,400,"invalid_node_coverage","invalid coverage");return};var active bool;var fsRaw []byte;var oldHandling int;err:=a.db.QueryRowContext(r.Context(),`SELECT active,functions,handling_minutes FROM lablogix.locations WHERE id=$1`,in.LocationID).Scan(&active,&fsRaw,&oldHandling);if err==sql.ErrNoRows{fail(w,404,"not_found","location not found");return};if err!=nil{handleErr(w,err);return};fs:=boolMap(fsRaw);if in.Functions!=nil{if !validFunctions(in.Functions){fail(w,400,"invalid_location_function","invalid location functions");return};fs=functionMap(in.Functions)};if in.HandlingMinutes==0{in.HandlingMinutes=oldHandling};_,err=a.db.ExecContext(r.Context(),`UPDATE lablogix.locations SET name=$2,latitude=$3,longitude=$4,coverage_km=$5,handling_minutes=$6,functions=$7 WHERE id=$1`,in.LocationID,in.Name,in.Coordinate.Latitude,in.Coordinate.Longitude,in.CoverageKm,in.HandlingMinutes,jsonBytes(fs));if err!=nil{handleErr(w,err);return};a.bumpNetwork(r.Context());a.audit(r.Context(),s,"update_location","location",in.LocationID,true,in);data(w,201,locationResponse(in.LocationID,in.Name,in.Coordinate,in.CoverageKm,in.HandlingMinutes,active,fs))}
func (a *App) setLocationStatus(w http.ResponseWriter,r *http.Request,s *Session){if !requireRole(w,s,"administrator"){return};var in struct{LocationID string `json:"locationId"`;Active bool `json:"active"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};res,err:=a.db.ExecContext(r.Context(),`UPDATE lablogix.locations SET active=$2 WHERE id=$1`,in.LocationID,in.Active);if err!=nil{handleErr(w,err);return};n,_:=res.RowsAffected();if n==0{fail(w,404,"not_found","location not found");return};a.bumpNetwork(r.Context());a.audit(r.Context(),s,"set_location_status","location",in.LocationID,true,in);data(w,200,map[string]any{"locationId":in.LocationID,"active":in.Active})}
func (a *App) setLocationFunctionStatus(w http.ResponseWriter,r *http.Request,s *Session){if !requireRole(w,s,"administrator"){return};var in struct{LocationID string `json:"locationId"`;Function string `json:"function"`;Active bool `json:"active"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if _,ok:=functionMap([]string{})[in.Function];!ok{fail(w,400,"invalid_location_function","invalid function");return};var raw []byte;if err:=a.db.QueryRowContext(r.Context(),`SELECT functions FROM lablogix.locations WHERE id=$1`,in.LocationID).Scan(&raw);err==sql.ErrNoRows{fail(w,404,"not_found","location not found");return}else if err!=nil{handleErr(w,err);return};fs:=boolMap(raw);fs[in.Function]=in.Active;_,err:=a.db.ExecContext(r.Context(),`UPDATE lablogix.locations SET functions=$2 WHERE id=$1`,in.LocationID,jsonBytes(fs));if err!=nil{handleErr(w,err);return};a.bumpNetwork(r.Context());a.audit(r.Context(),s,"set_location_function_status","location",in.LocationID,true,in);data(w,200,map[string]any{"locationId":in.LocationID,"function":in.Function,"active":in.Active,"functions":fs})}

func (a *App) createConnection(w http.ResponseWriter,r *http.Request,s *Session){if !requireRole(w,s,"administrator"){return};var in struct{FromLocationID string `json:"fromLocationId"`;ToLocationID string `json:"toLocationId"`;TravelMinutes int `json:"travelMinutes"`;CostUnits float64 `json:"costUnits"`;Cooled bool `json:"cooled"`;Active bool `json:"active"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if in.FromLocationID==in.ToLocationID||in.TravelMinutes<=0||in.CostUnits<0{fail(w,400,"invalid_connection","invalid connection");return};id:=uuid();err:=a.transaction(r.Context(),func(tx *sql.Tx)error{if _,e:=tx.ExecContext(r.Context(),`INSERT INTO lablogix.connections(id,from_location_id,to_location_id,travel_minutes,cost_units,cooled,active) VALUES($1,$2,$3,$4,$5,$6,$7)`,id,in.FromLocationID,in.ToLocationID,in.TravelMinutes,in.CostUnits,in.Cooled,in.Active);e!=nil{return e};_,e:=tx.ExecContext(r.Context(),`INSERT INTO lablogix.capacities(resource_id) VALUES($1)`,id);return e});if err!=nil{handleErr(w,err);return};a.bumpNetwork(r.Context());a.audit(r.Context(),s,"create_connection","connection",id,true,in);data(w,201,map[string]any{"connectionId":id,"fromLocationId":in.FromLocationID,"toLocationId":in.ToLocationID,"travelMinutes":in.TravelMinutes,"costUnits":in.CostUnits,"cooled":in.Cooled,"active":in.Active})}
func (a *App) setConnectionStatus(w http.ResponseWriter,r *http.Request,s *Session){if !requireRole(w,s,"administrator"){return};var in struct{ConnectionID string `json:"connectionId"`;Active bool `json:"active"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};res,err:=a.db.ExecContext(r.Context(),`UPDATE lablogix.connections SET active=$2 WHERE id=$1`,in.ConnectionID,in.Active);if err!=nil{handleErr(w,err);return};n,_:=res.RowsAffected();if n==0{fail(w,404,"not_found","connection not found");return};a.bumpNetwork(r.Context());a.audit(r.Context(),s,"set_connection_status","connection",in.ConnectionID,true,in);data(w,200,map[string]any{"connectionId":in.ConnectionID,"active":in.Active})}
func (a *App) configureLabAcceptance(w http.ResponseWriter,r *http.Request,s *Session){if !requireRole(w,s,"administrator"){return};var in struct{LaboratoryID string `json:"laboratoryId"`;SampleTypeID string `json:"sampleTypeId"`;Accepts bool `json:"accepts"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};id:=uuid();err:=a.db.QueryRowContext(r.Context(),`INSERT INTO lablogix.laboratory_acceptance(id,laboratory_id,sample_type_id,accepts) VALUES($1,$2,$3,$4) ON CONFLICT(laboratory_id,sample_type_id) DO UPDATE SET accepts=EXCLUDED.accepts RETURNING id`,id,in.LaboratoryID,in.SampleTypeID,in.Accepts).Scan(&id);if err!=nil{handleErr(w,err);return};a.bumpNetwork(r.Context());a.audit(r.Context(),s,"configure_laboratory_acceptance","location",in.LaboratoryID,true,in);data(w,200,map[string]any{"acceptanceId":id,"accepts":in.Accepts})}
func (a *App) configureCapacity(w http.ResponseWriter,r *http.Request,s *Session){var in struct{ResourceID string `json:"resourceId"`;CapacityUnits int `json:"capacityUnits"`;CooledCapacityUnits int `json:"cooledCapacityUnits"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if in.CapacityUnits<0||in.CooledCapacityUnits<0{fail(w,400,"invalid_capacity","capacity cannot be negative");return};if !s.hasRole("administrator") {if !s.hasRole("node_handler","laboratory_team")||s.AssignedLocationID!=in.ResourceID{fail(w,403,"forbidden","capacity is outside your assigned location");return}};var reserved,cooledReserved int;err:=a.db.QueryRowContext(r.Context(),`SELECT reserved_units,cooled_reserved_units FROM lablogix.capacities WHERE resource_id=$1`,in.ResourceID).Scan(&reserved,&cooledReserved);if err==sql.ErrNoRows{fail(w,404,"not_found","capacity resource not found");return};if err!=nil{handleErr(w,err);return};if in.CapacityUnits<reserved||in.CooledCapacityUnits<cooledReserved{fail(w,409,"capacity_reserved","configured capacity cannot fall below reservations");return};_,err=a.db.ExecContext(r.Context(),`UPDATE lablogix.capacities SET capacity_units=$2,cooled_capacity_units=$3 WHERE resource_id=$1`,in.ResourceID,in.CapacityUnits,in.CooledCapacityUnits);if err!=nil{handleErr(w,err);return};a.bumpNetwork(r.Context());a.audit(r.Context(),s,"configure_capacity","capacity",in.ResourceID,true,in);data(w,200,map[string]any{"resourceId":in.ResourceID,"capacityUnits":in.CapacityUnits,"cooledCapacityUnits":in.CooledCapacityUnits})}
func (a *App) setWorkerAvailability(w http.ResponseWriter,r *http.Request,s *Session){var in struct{WorkerID string `json:"workerId"`;Available bool `json:"available"`;CapacityUnits int `json:"capacityUnits"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if s.UserID!=in.WorkerID&&!s.hasRole("administrator","dispatcher"){fail(w,403,"forbidden","cannot change another worker");return};if in.CapacityUnits<0{fail(w,400,"invalid_capacity","capacity cannot be negative");return};res,err:=a.db.ExecContext(r.Context(),`UPDATE lablogix.users SET available=$2,capacity_units=$3 WHERE id=$1`,in.WorkerID,in.Available,in.CapacityUnits);if err!=nil{handleErr(w,err);return};n,_:=res.RowsAffected();if n==0{fail(w,404,"not_found","worker not found");return};a.audit(r.Context(),s,"set_worker_availability","user",in.WorkerID,true,in);data(w,200,map[string]any{"workerId":in.WorkerID,"available":in.Available,"capacityUnits":in.CapacityUnits})}

