package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"math"
	"net/http"
	"sort"
	"time"

	"github.com/lib/pq"
)

type serviceInput struct{Origin coordinate `json:"origin"`;OriginType string `json:"originType"`;OriginNodeID string `json:"originNodeId"`;SampleTypeID string `json:"sampleTypeId"`;RequestedAt string `json:"requestedAt"`;DeliveryDeadline string `json:"deliveryDeadline"`;EarliestCollectionAt string `json:"earliestCollectionAt"`;LatestCollectionAt string `json:"latestCollectionAt"`}
type routeEdge struct{ID,From,To string;Minutes int;Cost float64}
type serviceResult struct{Serviceable bool;Reason,LabID,StartNodeID string;Estimated time.Time;Version int;Edges []routeEdge;Cooled bool}
type nodePoint struct{ID,Name string;Lat,Lon,Coverage float64;Handling int;Functions map[string]bool}

func validateServiceInput(in *serviceInput)(time.Time,time.Time,time.Time,error){
	if !validCoord(in.Origin){return time.Time{},time.Time{},time.Time{},asError("invalid_origin","invalid origin coordinate",400)}
	if in.OriginType==""{in.OriginType="home"};if in.OriginType!="home"&&in.OriginType!="clinic"&&in.OriginType!="node"{return time.Time{},time.Time{},time.Time{},asError("invalid_origin_type","invalid origin type",400)};if in.OriginType=="node"&&in.OriginNodeID==""{return time.Time{},time.Time{},time.Time{},asError("invalid_origin","originNodeId is required",400)}
	req,e:=parseTime(in.RequestedAt);if e!=nil{return time.Time{},time.Time{},time.Time{},e};deadline,e:=parseTime(in.DeliveryDeadline);if e!=nil{return time.Time{},time.Time{},time.Time{},e};earliest:=req;if in.EarliestCollectionAt!=""{earliest,e=parseTime(in.EarliestCollectionAt);if e!=nil{return time.Time{},time.Time{},time.Time{},e}};latest:=earliest;if in.LatestCollectionAt!=""{latest,e=parseTime(in.LatestCollectionAt);if e!=nil{return time.Time{},time.Time{},time.Time{},e}}
	if latest.Before(earliest){return time.Time{},time.Time{},time.Time{},asError("invalid_collection_window","latest collection must not precede earliest",400)};if !deadline.After(req)||!deadline.After(earliest){return time.Time{},time.Time{},time.Time{},asError("invalid_deadline","delivery deadline must follow collection",400)};return earliest,latest,deadline,nil
}

func (a *App) serviceability(ctx context.Context,in *serviceInput)(serviceResult,error){
	earliest,_,deadline,e:=validateServiceInput(in);if e!=nil{return serviceResult{},e};var version int;if e=a.db.QueryRowContext(ctx,`SELECT published_serviceability_version FROM lablogix.network_meta WHERE singleton`).Scan(&version);e!=nil{return serviceResult{},e}
	res:=serviceResult{Reason:"outside_service_coverage",Version:version}
	var cooled bool;var stActive bool;e=a.db.QueryRowContext(ctx,`SELECT requires_cooled_route,active FROM lablogix.sample_types WHERE id=$1`,in.SampleTypeID).Scan(&cooled,&stActive);if e==sql.ErrNoRows{return res,asError("not_found","sample type not found",404)};if e!=nil{return res,e};res.Cooled=cooled;if !stActive{res.Reason="handling_rules_unsatisfiable";return res,nil}
