package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/lib/pq"
)

func (a *App) canSeeSample(ctx context.Context,s *Session,id string)bool{if s.hasRole("administrator","dispatcher"){return true};var n int;if s.ActiveRole=="requester"{_ =a.db.QueryRowContext(ctx,`SELECT count(*) FROM lablogix.samples WHERE id=$1 AND requester_id=$2`,id,s.UserID).Scan(&n)}else{_ =a.db.QueryRowContext(ctx,`SELECT count(*) FROM lablogix.assignments WHERE sample_id=$1 AND (worker_id=$2 OR offered_worker_id=$2)`,id,s.UserID).Scan(&n)};return n>0}
func (a *App) timeline(ctx context.Context,entityType,entityID string)[]map[string]any{rows,e:=a.db.QueryContext(ctx,`SELECT id,action,actor_id,actor_role,success,occurred_at,details FROM lablogix.audit_logs WHERE entity_type=$1 AND entity_id=$2 ORDER BY occurred_at,id`,entityType,entityID);if e!=nil{return []map[string]any{}};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id int64;var action,actor,role string;var success bool;var at time.Time;var raw []byte;_ =rows.Scan(&id,&action,&actor,&role,&success,&at,&raw);out=append(out,map[string]any{"eventId":id,"action":action,"actorId":actor,"role":role,"entityType":entityType,"entityId":entityID,"success":success,"occurredAt":timeText(at),"details":scanJSON(raw)})};return out}
func stale(t sql.NullTime)bool{return !t.Valid||time.Since(t.Time)>15*time.Minute}

func (a *App) uiBootstrap(w http.ResponseWriter,r *http.Request,s *Session){if r.Method!=http.MethodGet{fail(w,405,"method_not_allowed","method not allowed");return};u:=map[string]any{"userId":s.UserID,"username":s.Username,"roles":[]string(s.Roles),"activeRole":s.ActiveRole,"roleSelectionRequired":s.ActiveRole==""};if s.FullName!=""{u["fullName"]=s.FullName};out:=map[string]any{"user":u,"serverTime":timeText(time.Now())};if s.ActiveRole=="requester"{rows,_:=a.db.QueryContext(r.Context(),`SELECT id,status,serviceability,created_at FROM lablogix.samples WHERE requester_id=$1 ORDER BY created_at DESC LIMIT 100`,s.UserID);items:=[]map[string]any{};if rows!=nil{defer rows.Close();for rows.Next(){var id,status,service string;var at time.Time;_ =rows.Scan(&id,&status,&service,&at);items=append(items,map[string]any{"sampleId":id,"status":status,"serviceability":service,"createdAt":timeText(at)})}};out["requesterSamples"]=items};if s.hasRole("administrator","dispatcher"){out["operations"]=a.operations(r.Context(),"")};data(w,200,out)}

func (a *App) readSampleState(w http.ResponseWriter,r *http.Request,s *Session,id string){if r.Method!=http.MethodGet{fail(w,405,"method_not_allowed","method not allowed");return};if !a.canSeeSample(r.Context(),s,id){fail(w,403,"forbidden","sample is outside your role scope");return};var requestID,requesterID,originType,requested,deadline,typeID,container,service,status string;var lat,lon,tmin,tmax float64;var incompat pq.StringArray;var assignments pq.StringArray;var journey,lab sql.NullString;var llat,llon sql.NullFloat64;var recorded sql.NullTime
	err:=a.db.QueryRowContext(r.Context(),`SELECT s.request_id,s.requester_id,r.origin_latitude,r.origin_longitude,r.origin_type,r.requested_at::text,r.delivery_deadline::text,s.sample_type_id,s.container_type,s.temperature_min_c,s.temperature_max_c,s.incompatible_sample_types,s.serviceability,s.status,COALESCE(array_agg(a.id) FILTER(WHERE a.status NOT IN('completed','cancelled')), '{}'),s.active_journey_id,s.target_laboratory_id,s.latest_latitude,s.latest_longitude,s.location_recorded_at FROM lablogix.samples s JOIN lablogix.collection_requests r ON r.id=s.request_id LEFT JOIN lablogix.assignments a ON a.sample_id=s.id WHERE s.id=$1 GROUP BY s.id,r.id`,id).Scan(&requestID,&requesterID,&lat,&lon,&originType,&requested,&deadline,&typeID,&container,&tmin,&tmax,&incompat,&service,&status,&assignments,&journey,&lab,&llat,&llon,&recorded);if err==sql.ErrNoRows{fail(w,404,"not_found","sample not found");return};if err!=nil{handleErr(w,err);return};m:=map[string]any{"sampleId":id,"requestId":requestID,"requesterId":requesterID,"origin":coordinate{lat,lon},"originType":originType,"requestedAt":normalizePGTime(requested),"deliveryDeadline":normalizePGTime(deadline),"sampleTypeId":typeID,"containerType":container,"temperatureMinC":tmin,"temperatureMaxC":tmax,"incompatibleSampleTypes":[]string(incompat),"serviceability":service,"activeAssignmentIds":[]string(assignments),"state":map[string]any{"status":status},"timeline":a.timeline(r.Context(),"sample",id),"locationStale":stale(recorded)};if journey.Valid{m["activeJourneyId"]=journey.String};if lab.Valid{m["targetLaboratoryId"]=lab.String};if llat.Valid&&llon.Valid{m["latestLocation"]=coordinate{llat.Float64,llon.Float64}};if recorded.Valid{m["locationRecordedAt"]=timeText(recorded.Time)};data(w,200,m)}
func normalizePGTime(v string)string{if t,e:=time.Parse("2006-01-02 15:04:05.999999-07",v);e==nil{return timeText(t)};if t,e:=time.Parse(time.RFC3339,v);e==nil{return timeText(t)};return v}

func (a *App) readSampleLifecycle(w http.ResponseWriter,r *http.Request,s *Session){var in struct{SampleID string `json:"sampleId"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if !a.canSeeSample(r.Context(),s,in.SampleID){fail(w,403,"forbidden","sample is outside your role scope");return};var status string;var sealed bool;var holder,journey,lab sql.NullString;var exceptionRaw []byte;var llat,llon sql.NullFloat64;var recorded sql.NullTime;err:=a.db.QueryRowContext(r.Context(),`SELECT status,sealed,current_holder_id,active_journey_id,received_laboratory_id,COALESCE(exception,'null'),latest_latitude,latest_longitude,location_recorded_at FROM lablogix.samples WHERE id=$1`,in.SampleID).Scan(&status,&sealed,&holder,&journey,&lab,&exceptionRaw,&llat,&llon,&recorded);if err==sql.ErrNoRows{fail(w,404,"not_found","sample not found");return};if err!=nil{handleErr(w,err);return};rows,_:=a.db.QueryContext(r.Context(),`SELECT id FROM lablogix.assignments WHERE sample_id=$1 AND status='completed' ORDER BY sequence`,in.SampleID);completed:=[]string{};if rows!=nil{defer rows.Close();for rows.Next(){var id string;_=rows.Scan(&id);completed=append(completed,id)}};repls:=[]string{};if journey.Valid{rr,_:=a.db.QueryContext(r.Context(),`SELECT id FROM lablogix.journeys WHERE parent_journey_id=$1 AND active`,journey.String);if rr!=nil{defer rr.Close();for rr.Next(){var id string;_=rr.Scan(&id);repls=append(repls,id)}}};m:=map[string]any{"sampleId":in.SampleID,"status":status,"sealed":sealed,"completedLegIds":completed,"activeReplacementPlanIds":repls,"timeline":a.timeline(r.Context(),"sample",in.SampleID),"locationStale":stale(recorded)};if holder.Valid{m["currentHolderId"]=holder.String};if journey.Valid{m["activeJourneyId"]=journey.String};if lab.Valid{m["receivedLaboratoryId"]=lab.String};if string(exceptionRaw)!="null"{var ex map[string]any;_=json.Unmarshal(exceptionRaw,&ex);m["exception"]=ex};var hid string;var hraw []byte;if e:=a.db.QueryRowContext(r.Context(),`SELECT id,to_jsonb(handoffs) FROM lablogix.handoffs WHERE sample_id=$1 AND status='pending' ORDER BY initiated_at DESC LIMIT 1`,in.SampleID).Scan(&hid,&hraw);e==nil{m["pendingHandoffId"]=hid;m["pendingHandoff"]=scanJSON(hraw)};if llat.Valid&&llon.Valid{m["latestLocation"]=coordinate{llat.Float64,llon.Float64}};if recorded.Valid{m["locationRecordedAt"]=timeText(recorded.Time)};data(w,200,m)}

func (a *App) listRoleWork(w http.ResponseWriter,r *http.Request,s *Session){var in struct{Role string `json:"role"`;Status string `json:"status"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};role:=in.Role;if role==""{role=s.ActiveRole};if role!=s.ActiveRole{fail(w,403,"forbidden","work role must match active role");return};pending,inProgress,completed:=[]any{},[]any{},[]any{}
	if role=="requester"{rows,e:=a.db.QueryContext(r.Context(),`SELECT s.id,s.request_id,s.status,s.serviceability,r.requested_at,r.delivery_deadline,r.earliest_collection_at,r.latest_collection_at,s.active_journey_id,s.target_laboratory_id,s.current_holder_id,s.location_recorded_at FROM lablogix.samples s JOIN lablogix.collection_requests r ON r.id=s.request_id WHERE s.requester_id=$1 ORDER BY s.created_at DESC`,s.UserID);if e!=nil{handleErr(w,e);return};defer rows.Close();for rows.Next(){var id,rid,status,service string;var req,deadline,early,late time.Time;var journey,lab,holder sql.NullString;var loc sql.NullTime;_ =rows.Scan(&id,&rid,&status,&service,&req,&deadline,&early,&late,&journey,&lab,&holder,&loc);m:=map[string]any{"kind":"sample","sampleId":id,"requestId":rid,"status":status,"serviceability":service,"requestedAt":timeText(req),"deliveryDeadline":timeText(deadline),"earliestCollectionAt":timeText(early),"latestCollectionAt":timeText(late),"history":a.timeline(r.Context(),"sample",id),"locationStale":stale(loc),"requesterId":s.UserID};if journey.Valid{m["journeyId"]=journey.String;m["activeJourneyId"]=journey.String};if lab.Valid{m["laboratoryId"]=lab.String};if holder.Valid{m["currentHolderId"]=holder.String};if loc.Valid{m["locationRecordedAt"]=timeText(loc.Time)};bucket(status,&pending,&inProgress,&completed,m)}}else if role=="dispatcher"||role=="administrator"{rows,e:=a.db.QueryContext(r.Context(),`SELECT j.id,j.status,j.route_mode,j.plan_version,j.estimated_delivery_at,(SELECT array_agg(sample_id) FROM lablogix.journey_samples WHERE journey_id=j.id),(SELECT count(*) FROM lablogix.assignments WHERE journey_id=j.id) FROM lablogix.journeys j ORDER BY created_at DESC`);if e!=nil{handleErr(w,e);return};defer rows.Close();for rows.Next(){var id,status,mode string;var ver,count int;var est sql.NullTime;var ids pq.StringArray;_ =rows.Scan(&id,&status,&mode,&ver,&est,&ids,&count);m:=map[string]any{"kind":"journey","journeyId":id,"status":status,"routeMode":mode,"planVersion":ver,"sampleIds":[]string(ids),"estimatedDeliveryAt":func()string{if est.Valid{return timeText(est.Time)};return timeText(time.Now())}(),"assignmentCount":count,"history":a.timeline(r.Context(),"journey",id)};bucket(status,&pending,&inProgress,&completed,m)}}else{rows,e:=a.db.QueryContext(r.Context(),`SELECT a.id,a.sample_id,a.kind,a.status,a.journey_id,a.from_location_id,a.to_location_id,a.sequence,a.offer_expires_at,a.node_id,a.laboratory_id FROM lablogix.assignments a WHERE a.offered_worker_id=$1 OR a.worker_id=$1 ORDER BY a.created_at DESC`,s.UserID);if e!=nil{handleErr(w,e);return};defer rows.Close();for rows.Next(){var id,sid,kind,status,jid string;var from,to,node,lab sql.NullString;var seq int;var expiry sql.NullTime;_=rows.Scan(&id,&sid,&kind,&status,&jid,&from,&to,&seq,&expiry,&node,&lab);m:=map[string]any{"kind":kind,"assignmentId":id,"sampleId":sid,"status":status,"journeyId":jid,"sequence":seq,"history":a.timeline(r.Context(),"assignment",id)};if from.Valid{m["fromLocationId"]=from.String};if to.Valid{m["toLocationId"]=to.String};if node.Valid{m["nodeId"]=node.String};if lab.Valid{m["laboratoryId"]=lab.String};if expiry.Valid{m["offerExpiresAt"]=timeText(expiry.Time)};if kind=="laboratory"&&lab.Valid{if cap:=a.capacity(r.Context(),lab.String);cap!=nil{m["destinationCapacity"]=cap}};bucket(status,&pending,&inProgress,&completed,m)}};data(w,200,map[string]any{"pending":pending,"inProgress":inProgress,"completed":completed})}
func bucket(status string,pending,inProgress,completed *[]any,item any){switch status{case"received","completed","cancelled","declined":*completed=append(*completed,item);case"accepted","in_progress","at_pickup","picked_up","in_transit","arrived","delivered","sealed":*inProgress=append(*inProgress,item);default:*pending=append(*pending,item)}}
func (a *App) capacity(ctx context.Context,id string)map[string]any{var c,r,cc,cr int;if a.db.QueryRowContext(ctx,`SELECT capacity_units,reserved_units,cooled_capacity_units,cooled_reserved_units FROM lablogix.capacities WHERE resource_id=$1`,id).Scan(&c,&r,&cc,&cr)!=nil{return nil};return map[string]any{"capacityUnits":c,"reservedUnits":r,"availableUnits":c-r,"cooledCapacityUnits":cc,"cooledReservedUnits":cr,"cooledAvailableUnits":cc-cr}}

func (a *App) readOperationsState(w http.ResponseWriter,r *http.Request,s *Session){if !requireRole(w,s,"administrator","dispatcher"){return};var in struct{Filters map[string]string `json:"filters"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};filter:="";if in.Filters!=nil{filter=in.Filters["sampleTypeId"];if filter==""{filter=in.Filters["sample_type_id"]}};data(w,200,a.operations(r.Context(),filter))}
func (a *App) operations(ctx context.Context,filter string)map[string]any{samples:=[]map[string]any{};args:=[]any{};where:="";if filter!=""{where=" WHERE sample_type_id=$1";args=append(args,filter)};rows,_:=a.db.QueryContext(ctx,`SELECT id,status,request_id,active_journey_id,current_holder_id,latest_latitude,latest_longitude,location_recorded_at FROM lablogix.samples`+where+` ORDER BY created_at DESC`,args...);if rows!=nil{defer rows.Close();for rows.Next(){var id,status,rid string;var journey,holder sql.NullString;var lat,lon sql.NullFloat64;var rec sql.NullTime;_=rows.Scan(&id,&status,&rid,&journey,&holder,&lat,&lon,&rec);m:=map[string]any{"sampleId":id,"status":status,"requestId":rid,"locationStale":stale(rec)};if journey.Valid{m["activeJourneyId"]=journey.String};if holder.Valid{m["currentHolderId"]=holder.String};if lat.Valid&&lon.Valid{m["latestLocation"]=coordinate{lat.Float64,lon.Float64}};if rec.Valid{m["locationRecordedAt"]=timeText(rec.Time)};samples=append(samples,m)}};workers:=[]map[string]any{};wr,_:=a.db.QueryContext(ctx,`SELECT u.id,COALESCE(u.full_name,''),u.roles,u.available,u.capacity_units,(SELECT count(*) FROM lablogix.assignments a WHERE a.worker_id=u.id AND a.status NOT IN('completed','cancelled')),w.latitude,w.longitude,w.recorded_at FROM lablogix.users u LEFT JOIN LATERAL(SELECT latitude,longitude,recorded_at FROM lablogix.worker_locations WHERE worker_id=u.id ORDER BY recorded_at DESC LIMIT 1)w ON true WHERE u.roles&&ARRAY['collection_professional','delivery_partner','node_handler','laboratory_team']::text[]`);counts:=[]int{};if wr!=nil{defer wr.Close();for wr.Next(){var id,name string;var roles pq.StringArray;var avail bool;var cap,count int;var lat,lon sql.NullFloat64;var rec sql.NullTime;_=wr.Scan(&id,&name,&roles,&avail,&cap,&count,&lat,&lon,&rec);m:=map[string]any{"workerId":id,"fullName":name,"roles":[]string(roles),"available":avail,"status":map[bool]string{true:"available",false:"unavailable"}[avail],"capacityUnits":cap,"assignmentCount":count,"locationStale":stale(rec)};if lat.Valid&&lon.Valid{m["latestLocation"]=coordinate{lat.Float64,lon.Float64}};if rec.Valid{m["locationRecordedAt"]=timeText(rec.Time)};workers=append(workers,m);counts=append(counts,count)}};locations:=[]map[string]any{};lr,_:=a.db.QueryContext(ctx,`SELECT id,name,latitude,longitude,active,coverage_km,handling_minutes,functions FROM lablogix.locations ORDER BY name`);if lr!=nil{defer lr.Close();for lr.Next(){var id,name string;var lat,lon,cov float64;var active bool;var handling int;var raw []byte;_=lr.Scan(&id,&name,&lat,&lon,&active,&cov,&handling,&raw);m:=map[string]any{"id":id,"locationId":id,"name":name,"coordinate":coordinate{lat,lon},"active":active,"coverageKm":cov,"handlingMinutes":handling,"functions":boolMap(raw)};if c:=a.capacity(ctx,id);c!=nil{m["capacity"]=c};acc:=[]string{};ar,_:=a.db.QueryContext(ctx,`SELECT sample_type_id FROM lablogix.laboratory_acceptance WHERE laboratory_id=$1 AND accepts`,id);if ar!=nil{for ar.Next(){var x string;_=ar.Scan(&x);acc=append(acc,x)};ar.Close()};m["acceptedSampleTypeIds"]=acc;locations=append(locations,m)}};connections:=[]map[string]any{};cr,_:=a.db.QueryContext(ctx,`SELECT id,from_location_id,to_location_id,travel_minutes,cost_units,cooled,active FROM lablogix.connections`);if cr!=nil{defer cr.Close();for cr.Next(){var id,f,t string;var mins int;var cost float64;var cooled,active bool;_=cr.Scan(&id,&f,&t,&mins,&cost,&cooled,&active);m:=map[string]any{"id":id,"connectionId":id,"fromLocationId":f,"toLocationId":t,"travelMinutes":mins,"costUnits":cost,"cooled":cooled,"active":active};if c:=a.capacity(ctx,id);c!=nil{m["capacity"]=c};connections=append(connections,m)}};handoffs:=[]map[string]any{};hr,_:=a.db.QueryContext(ctx,`SELECT id,sample_id,sender_id,receiver_id,status,sender_confirmed,receiver_confirmed FROM lablogix.handoffs WHERE status='pending'`);if hr!=nil{defer hr.Close();for hr.Next(){var id,sid,se,re,status string;var sc,rc bool;_=hr.Scan(&id,&sid,&se,&re,&status,&sc,&rc);handoffs=append(handoffs,map[string]any{"handoffId":id,"sampleId":sid,"senderId":se,"receiverId":re,"status":status,"senderConfirmed":sc,"receiverConfirmed":rc})}};exceptions:=[]map[string]any{};er,_:=a.db.QueryContext(ctx,`SELECT id,sample_id,reason,kind,observed_at FROM lablogix.sample_exceptions WHERE NOT resolved ORDER BY observed_at DESC`);if er!=nil{defer er.Close();for er.Next(){var id,sid,reason,kind string;var at time.Time;_=er.Scan(&id,&sid,&reason,&kind,&at);exceptions=append(exceptions,map[string]any{"exceptionId":id,"sampleId":sid,"reason":reason,"kind":kind,"observedAt":timeText(at)})}};spread:=0;if len(counts)>0{min,max:=counts[0],counts[0];for _,x:=range counts{if x<min{min=x};if x>max{max=x}};spread=max-min};return map[string]any{"samples":samples,"workers":workers,"locations":locations,"connections":connections,"routes":[]any{},"handoffs":handoffs,"delays":[]any{},"exceptions":exceptions,"assignmentCountSpread":spread,"ineligibleAssignmentCount":0}}

func (a *App) readServiceabilitySnapshot(w http.ResponseWriter,r *http.Request,s *Session){if !requireRole(w,s,"administrator","dispatcher"){return};var in map[string]any;if err:=decode(r,&in);err!=nil{handleErr(w,err);return};var ver,rev int;var at time.Time;var raw []byte;err:=a.db.QueryRowContext(r.Context(),`SELECT version,computed_at,network_revision,regions FROM lablogix.serviceability_snapshots WHERE status='complete' ORDER BY version DESC LIMIT 1`).Scan(&ver,&at,&rev,&raw);if err!=nil{handleErr(w,err);return};var regions []any;_=json.Unmarshal(raw,&regions);data(w,200,map[string]any{"version":ver,"status":"complete","computedAt":timeText(at),"networkRevision":rev,"regions":regions,"activeCollectionPointCount":len(regions)})}

func (a *App) events(w http.ResponseWriter,r *http.Request,s *Session){if r.Method!=http.MethodGet{fail(w,405,"method_not_allowed","method not allowed");return};since,_:=strconv.ParseInt(r.URL.Query().Get("since"),10,64);rows,e:=a.db.QueryContext(r.Context(),`SELECT id,event_type,entity_type,entity_id,payload,created_at FROM lablogix.realtime_events WHERE id>$1 ORDER BY id LIMIT 200`,since);if e!=nil{handleErr(w,e);return};defer rows.Close();events:=[]map[string]any{};cursor:=since;for rows.Next(){var id int64;var typ,et,eid string;var raw []byte;var at time.Time;_=rows.Scan(&id,&typ,&et,&eid,&raw,&at);if id>cursor{cursor=id};events=append(events,map[string]any{"id":id,"type":typ,"entityType":et,"entityId":eid,"payload":scanJSON(raw),"createdAt":timeText(at)})};data(w,200,map[string]any{"events":events,"cursor":cursor})}

func (a *App) searchAudit(w http.ResponseWriter,r *http.Request,s *Session){if !requireRole(w,s,"administrator","dispatcher"){return};var in struct{Query,ActorID,EntityType,EntityID,Action,Role,FromTime,ToTime,Order string;Success *bool `json:"success"`;Limit int `json:"limit"`;Offset int `json:"offset"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if in.Limit==0{in.Limit=50};if in.Limit<1||in.Limit>500||in.Offset<0{fail(w,400,"invalid_pagination","invalid pagination");return};conds:=[]string{"1=1"};args:=[]any{};add:=func(sqlText string,v any){args=append(args,v);conds=append(conds,fmt.Sprintf(sqlText,len(args)))};if in.Query!=""{add(`(action ILIKE '%%'||$%d||'%%' OR entity_id ILIKE '%%'||$%d||'%%' OR details::text ILIKE '%%'||$%d||'%%')`,in.Query)};if in.ActorID!=""{add(`actor_id=$%d`,in.ActorID)};if in.EntityType!=""{add(`entity_type=$%d`,in.EntityType)};if in.EntityID!=""{add(`entity_id=$%d`,in.EntityID)};if in.Action!=""{add(`action=$%d`,in.Action)};if in.Role!=""{add(`actor_role=$%d`,in.Role)};if in.Success!=nil{add(`success=$%d`,*in.Success)};if in.FromTime!=""{t,e:=parseTime(in.FromTime);if e!=nil{handleErr(w,e);return};add(`occurred_at>=$%d`,t)};if in.ToTime!=""{t,e:=parseTime(in.ToTime);if e!=nil{handleErr(w,e);return};add(`occurred_at<=$%d`,t)};where:=strings.Join(conds," AND ");var total int;if e:=a.db.QueryRowContext(r.Context(),`SELECT count(*) FROM lablogix.audit_logs WHERE `+where,args...).Scan(&total);e!=nil{handleErr(w,e);return};order:="DESC";orderName:="newest_first";if in.Order=="oldest_first"{order="ASC";orderName=in.Order};q:=`SELECT id,actor_id,actor_role,action,entity_type,entity_id,success,occurred_at,details FROM lablogix.audit_logs WHERE `+where+` ORDER BY occurred_at `+order+`,id `+order+fmt.Sprintf(` LIMIT %d OFFSET %d`,in.Limit,in.Offset);rows,e:=a.db.QueryContext(r.Context(),q,args...);if e!=nil{handleErr(w,e);return};defer rows.Close();entries:=[]map[string]any{};for rows.Next(){var id int64;var actor,role,action,et,eid string;var success bool;var at time.Time;var raw []byte;_=rows.Scan(&id,&actor,&role,&action,&et,&eid,&success,&at,&raw);entries=append(entries,map[string]any{"auditId":strconv.FormatInt(id,10),"actorId":actor,"role":role,"actorRole":role,"action":action,"entityType":et,"entityId":eid,"success":success,"occurredAt":timeText(at),"details":scanJSON(raw)})};has:=in.Offset+len(entries)<total;m:=map[string]any{"entries":entries,"total":total,"returned":len(entries),"offset":in.Offset,"limit":in.Limit,"order":orderName,"hasMore":has};if has{m["nextOffset"]=in.Offset+len(entries)};data(w,200,m)}

