package main

import (
	"database/sql"
	"net/http"
	"time"
)

func (a *App) acceptAssignment(w http.ResponseWriter,r *http.Request,s *Session){if !s.hasRole("collection_professional","delivery_partner","node_handler","laboratory_team"){fail(w,403,"ineligible_worker","active role is not a worker role");return};var in struct{AssignmentID string `json:"assignmentId"`;IdempotencyKey string `json:"idempotencyKey"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if in.IdempotencyKey==""{fail(w,400,"idempotency_required","idempotencyKey is required");return};var worker,status,kind string;var expiry time.Time;err:=a.db.QueryRowContext(r.Context(),`SELECT COALESCE(offered_worker_id::text,''),status,kind,offer_expires_at FROM lablogix.assignments WHERE id=$1 FOR UPDATE`,in.AssignmentID).Scan(&worker,&status,&kind,&expiry);if err==sql.ErrNoRows{fail(w,404,"not_found","assignment not found");return};if err!=nil{handleErr(w,err);return};expected:=map[string]string{"collection":"collection_professional","transport":"delivery_partner","node":"node_handler","laboratory":"laboratory_team"}[kind];if s.ActiveRole!=expected{fail(w,403,"ineligible_worker","active role is not eligible");return};if worker!=s.UserID{fail(w,409,"offer_not_offered","assignment was offered to another worker");return};if status=="accepted"{data(w,201,map[string]any{"assignmentId":in.AssignmentID,"workerId":s.UserID,"status":"accepted"});return};if status!="pending"{fail(w,409,"assignment_inactive","assignment is inactive");return};if time.Now().After(expiry){fail(w,409,"offer_not_available","assignment offer expired");return};var available bool;_ =a.db.QueryRowContext(r.Context(),`SELECT available FROM lablogix.users WHERE id=$1`,s.UserID).Scan(&available);if !available{fail(w,409,"worker_unavailable","worker is unavailable");return};_,err=a.db.ExecContext(r.Context(),`UPDATE lablogix.assignments SET worker_id=$2,status='accepted' WHERE id=$1 AND status='pending'`,in.AssignmentID,s.UserID);if err!=nil{handleErr(w,err);return};a.audit(r.Context(),s,"accept_assignment","assignment",in.AssignmentID,true,map[string]any{"workerId":s.UserID});a.event(r.Context(),"assignment.accepted","assignment",in.AssignmentID,map[string]any{"workerId":s.UserID});data(w,201,map[string]any{"assignmentId":in.AssignmentID,"workerId":s.UserID,"status":"accepted"})}

func (a *App) declineAssignment(w http.ResponseWriter,r *http.Request,s *Session){var in struct{AssignmentID,Reason,DeclinedAt,IdempotencyKey string};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if in.IdempotencyKey==""{fail(w,400,"idempotency_required","idempotencyKey is required");return};at:=time.Now();var err error;if in.DeclinedAt!=""{at,err=parseTime(in.DeclinedAt);if err!=nil{handleErr(w,err);return}};var offered,status,kind string;var sample,node,lab sql.NullString;err=a.db.QueryRowContext(r.Context(),`SELECT COALESCE(offered_worker_id::text,''),status,kind,sample_id,node_id,laboratory_id FROM lablogix.assignments WHERE id=$1`,in.AssignmentID).Scan(&offered,&status,&kind,&sample,&node,&lab);if err==sql.ErrNoRows{fail(w,404,"not_found","assignment not found");return};if err!=nil{handleErr(w,err);return};if offered!=s.UserID{fail(w,403,"forbidden","only the offered worker may decline");return};if status!="pending"{fail(w,409,"assignment_inactive","assignment is inactive");return};role:=map[string]string{"collection":"collection_professional","transport":"delivery_partner","node":"node_handler","laboratory":"laboratory_team"}[kind];q:=`SELECT id FROM lablogix.users WHERE active AND available AND $1=ANY(roles) AND id<>$2`;args:=[]any{role,s.UserID};if node.Valid{q+=` AND assigned_location_id=$3`;args=append(args,node.String)}else if lab.Valid{q+=` AND assigned_location_id=$3`;args=append(args,lab.String)};q+=` ORDER BY decline_score,created_at LIMIT 1`;var next sql.NullString;_ =a.db.QueryRowContext(r.Context(),q,args...).Scan(&next);_,err=a.db.ExecContext(r.Context(),`UPDATE lablogix.assignments SET offered_worker_id=$2,worker_id=NULL,status='pending',declined_by=$3,declined_at=$4,offer_expires_at=now()+interval '15 minutes' WHERE id=$1`,in.AssignmentID,func()any{if next.Valid{return next.String};return nil}(),s.UserID,at);if err!=nil{handleErr(w,err);return};_,_=a.db.ExecContext(r.Context(),`UPDATE lablogix.users SET decline_score=LEAST(decline_score+1,10) WHERE id=$1`,s.UserID);a.audit(r.Context(),s,"decline_assignment","assignment",in.AssignmentID,true,map[string]any{"reason":in.Reason,"reofferedTo":next.String});m:=map[string]any{"assignmentId":in.AssignmentID,"status":"pending","declinedBy":s.UserID,"declinedAt":timeText(at)};if next.Valid{m["reofferedTo"]=next.String};data(w,201,m)}

func (a *App) collectSeal(w http.ResponseWriter,r *http.Request,s *Session){if !requireRole(w,s,"collection_professional"){return};var in struct{SampleID,AssignmentID,CollectedAt,ContainerType,IdempotencyKey string;ObservedTemperatureC float64 `json:"observedTemperatureC"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if in.IdempotencyKey==""{fail(w,400,"idempotency_required","idempotencyKey is required");return};at,err:=parseTime(in.CollectedAt);if err!=nil{handleErr(w,err);return};var status,worker,kind,container,qual string;var tmin,tmax float64;var early,late time.Time;var sealed bool;err=a.db.QueryRowContext(r.Context(),`SELECT a.status,COALESCE(a.worker_id::text,''),a.kind,s.container_type,s.temperature_min_c,s.temperature_max_c,t.required_qualification,r.earliest_collection_at,r.latest_collection_at,s.sealed FROM lablogix.assignments a JOIN lablogix.samples s ON s.id=a.sample_id JOIN lablogix.sample_types t ON t.id=s.sample_type_id JOIN lablogix.collection_requests r ON r.id=s.request_id WHERE a.id=$1 AND s.id=$2`,in.AssignmentID,in.SampleID).Scan(&status,&worker,&kind,&container,&tmin,&tmax,&qual,&early,&late,&sealed);if err==sql.ErrNoRows{fail(w,404,"not_found","sample or assignment not found");return};if err!=nil{handleErr(w,err);return};if sealed{var holder string;_ =a.db.QueryRowContext(r.Context(),`SELECT current_holder_id FROM lablogix.samples WHERE id=$1`,in.SampleID).Scan(&holder);data(w,201,map[string]any{"sampleId":in.SampleID,"status":"sealed","currentHolderId":holder,"sealedAt":timeText(at),"handlingCompliant":true});return};if kind!="collection"||worker!=s.UserID||status!="accepted"{fail(w,409,"collection_not_ready","collection assignment is not accepted by this worker");return};if at.Before(early)||at.After(late){fail(w,409,"outside_collection_window","collection time is outside the collection window");return};if qual!=""&&!contains(s.Qualifications,qual){fail(w,409,"certification_inactive","matching active qualification is required");return};compliant:=in.ContainerType==container&&in.ObservedTemperatureC>=tmin&&in.ObservedTemperatureC<=tmax;if !compliant{fail(w,400,"handling_noncompliant","observed handling is outside requirements");return};err=a.transaction(r.Context(),func(tx *sql.Tx)error{if _,e:=tx.ExecContext(r.Context(),`UPDATE lablogix.samples SET sealed=true,status='sealed',current_holder_id=$2,latest_latitude=COALESCE(latest_latitude,(SELECT origin_latitude FROM lablogix.collection_requests WHERE id=request_id)),latest_longitude=COALESCE(latest_longitude,(SELECT origin_longitude FROM lablogix.collection_requests WHERE id=request_id)),location_recorded_at=$3 WHERE id=$1 AND NOT sealed`,in.SampleID,s.UserID,at);e!=nil{return e};_,e:=tx.ExecContext(r.Context(),`UPDATE lablogix.assignments SET status='completed',completed_at=$2 WHERE id=$1`,in.AssignmentID,at);return e});if err!=nil{handleErr(w,err);return};a.audit(r.Context(),s,"collect_and_seal_sample","sample",in.SampleID,true,map[string]any{"assignmentId":in.AssignmentID,"containerType":in.ContainerType,"temperatureC":in.ObservedTemperatureC});a.audit(r.Context(),s,"complete_assignment","assignment",in.AssignmentID,true,map[string]any{"sampleId":in.SampleID});data(w,201,map[string]any{"sampleId":in.SampleID,"status":"sealed","currentHolderId":s.UserID,"sealedAt":timeText(at),"handlingCompliant":true})}

func (a *App) updateProgress(w http.ResponseWriter,r *http.Request,s *Session){var in struct{AssignmentID,Status,OccurredAt,IdempotencyKey string};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if in.IdempotencyKey==""{fail(w,400,"idempotency_required","idempotencyKey is required");return};at,err:=parseTime(in.OccurredAt);if err!=nil{handleErr(w,err);return};valid:=[]string{"at_pickup","picked_up","in_transit","arrived","delivered","in_progress","completed"};if !contains(valid,in.Status){fail(w,409,"invalid_transition","invalid progress status");return};var worker,sid,kind,current string;var sealed bool;err=a.db.QueryRowContext(r.Context(),`SELECT COALESCE(worker_id::text,''),sample_id,kind,status,(SELECT sealed FROM lablogix.samples WHERE id=sample_id) FROM lablogix.assignments WHERE id=$1`,in.AssignmentID).Scan(&worker,&sid,&kind,&current,&sealed);if err==sql.ErrNoRows{fail(w,404,"not_found","assignment not found");return};if err!=nil{handleErr(w,err);return};if worker!=s.UserID{fail(w,403,"ineligible_worker","assignment belongs to another worker");return};if current=="pending"{fail(w,409,"assignment_not_ready","assignment must be accepted");return};if kind=="transport"&&!sealed{fail(w,409,"collection_required","sample must be sealed before transport");return};completed:=any(nil);if in.Status=="completed"||in.Status=="delivered"{completed=at};_,err=a.db.ExecContext(r.Context(),`UPDATE lablogix.assignments SET status=$2,completed_at=$3 WHERE id=$1`,in.AssignmentID,in.Status,completed);if err!=nil{handleErr(w,err);return};a.audit(r.Context(),s,"update_assignment_progress","assignment",in.AssignmentID,true,map[string]any{"status":in.Status,"occurredAt":timeText(at)});data(w,201,map[string]any{"assignmentId":in.AssignmentID,"sampleId":sid,"status":in.Status})}

func (a *App) recordWorkerLocation(w http.ResponseWriter,r *http.Request,s *Session){if !s.hasRole("collection_professional","delivery_partner"){fail(w,403,"forbidden","active role cannot report worker location");return};var in struct{AssignmentID string `json:"assignmentId"`;Coordinate coordinate `json:"coordinate"`;Sequence int `json:"sequence"`;RecordedAt string `json:"recordedAt"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if !validCoord(in.Coordinate)||in.Sequence<0{fail(w,400,"invalid_coordinate","invalid location update");return};at,err:=parseTime(in.RecordedAt);if err!=nil{handleErr(w,err);return};var worker,sid string;err=a.db.QueryRowContext(r.Context(),`SELECT COALESCE(worker_id::text,''),sample_id FROM lablogix.assignments WHERE id=$1`,in.AssignmentID).Scan(&worker,&sid);if err==sql.ErrNoRows{fail(w,404,"not_found","assignment not found");return};if worker!=s.UserID{fail(w,403,"forbidden","assignment belongs to another worker");return};_,err=a.db.ExecContext(r.Context(),`INSERT INTO lablogix.worker_locations(worker_id,assignment_id,latitude,longitude,sequence,recorded_at) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT(assignment_id,sequence) DO UPDATE SET latitude=EXCLUDED.latitude,longitude=EXCLUDED.longitude,recorded_at=EXCLUDED.recorded_at`,s.UserID,in.AssignmentID,in.Coordinate.Latitude,in.Coordinate.Longitude,in.Sequence,at);if err!=nil{handleErr(w,err);return};_,_=a.db.ExecContext(r.Context(),`UPDATE lablogix.samples SET latest_latitude=$2,latest_longitude=$3,location_recorded_at=$4 WHERE id=$1`,sid,in.Coordinate.Latitude,in.Coordinate.Longitude,at);a.audit(r.Context(),s,"record_worker_location","assignment",in.AssignmentID,true,map[string]any{"coordinate":in.Coordinate,"sequence":in.Sequence});data(w,201,map[string]any{"assignmentId":in.AssignmentID,"coordinate":in.Coordinate,"sequence":in.Sequence,"recordedAt":timeText(at)})}

func (a *App) initiateHandoff(w http.ResponseWriter,r *http.Request,s *Session){var in struct{SampleID,FromAssignmentID,ToAssignmentID,ReceiverID,InitiatedAt,IdempotencyKey string};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if in.IdempotencyKey==""{fail(w,400,"idempotency_required","idempotencyKey is required");return};at,err:=parseTime(in.InitiatedAt);if err!=nil{handleErr(w,err);return};var holder string;var sealed bool;err=a.db.QueryRowContext(r.Context(),`SELECT COALESCE(current_holder_id::text,''),sealed FROM lablogix.samples WHERE id=$1`,in.SampleID).Scan(&holder,&sealed);if err==sql.ErrNoRows{fail(w,404,"not_found","sample not found");return};if !sealed||holder!=s.UserID{fail(w,409,"custody_required","current holder must initiate the handoff");return};var receiver string;err=a.db.QueryRowContext(r.Context(),`SELECT COALESCE(worker_id::text,offered_worker_id::text,'') FROM lablogix.assignments WHERE id=$1 AND sample_id=$2`,in.ToAssignmentID,in.SampleID).Scan(&receiver);if err!=nil{fail(w,409,"invalid_assignment","receiving assignment is invalid");return};if receiver!=in.ReceiverID{fail(w,409,"invalid_receiver","receiver does not match the assignment");return};id:=uuid();err=a.db.QueryRowContext(r.Context(),`INSERT INTO lablogix.handoffs(id,sample_id,from_assignment_id,to_assignment_id,sender_id,receiver_id,initiated_at) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(sample_id,from_assignment_id,to_assignment_id) DO UPDATE SET initiated_at=lablogix.handoffs.initiated_at RETURNING id`,id,in.SampleID,in.FromAssignmentID,in.ToAssignmentID,s.UserID,in.ReceiverID,at).Scan(&id);if err!=nil{handleErr(w,err);return};a.audit(r.Context(),s,"initiate_handoff","sample",in.SampleID,true,map[string]any{"handoffId":id,"receiverId":in.ReceiverID});data(w,201,map[string]any{"handoffId":id,"senderId":s.UserID,"receiverId":in.ReceiverID,"currentHolderId":s.UserID,"status":"pending"})}

func (a *App) confirmHandoff(w http.ResponseWriter,r *http.Request,s *Session){var in struct{HandoffID,ConfirmationSide,ConfirmedAt,IdempotencyKey string};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if in.IdempotencyKey==""{fail(w,400,"idempotency_required","idempotencyKey is required");return};at,err:=parseTime(in.ConfirmedAt);if err!=nil{handleErr(w,err);return};var sid,sender,receiver,status string;var sc,rc bool;err=a.transaction(r.Context(),func(tx *sql.Tx)error{if e:=tx.QueryRowContext(r.Context(),`SELECT sample_id,sender_id,receiver_id,status,sender_confirmed,receiver_confirmed FROM lablogix.handoffs WHERE id=$1 FOR UPDATE`,in.HandoffID).Scan(&sid,&sender,&receiver,&status,&sc,&rc);e!=nil{return e};if in.ConfirmationSide=="sender"{if s.UserID!=sender{return asError("forbidden","only sender may confirm sender side",403)};sc=true}else if in.ConfirmationSide=="receiver"{if s.UserID!=receiver{return asError("forbidden","only receiver may confirm receiver side",403)};rc=true}else{return asError("invalid_confirmation_side","invalid confirmation side",400)};if status=="confirmed"{return nil};newStatus:="pending";if sc&&rc{newStatus="confirmed";status=newStatus;if _,e:=tx.ExecContext(r.Context(),`UPDATE lablogix.samples SET current_holder_id=$2,status='in_transit',location_recorded_at=$3 WHERE id=$1`,sid,receiver,at);e!=nil{return e}};_,e:=tx.ExecContext(r.Context(),`UPDATE lablogix.handoffs SET sender_confirmed=$2,receiver_confirmed=$3,status=$4,completed_at=CASE WHEN $4='confirmed' THEN $5 ELSE completed_at END WHERE id=$1`,in.HandoffID,sc,rc,newStatus,at);status=newStatus;return e});if err==sql.ErrNoRows{fail(w,404,"not_found","handoff not found");return};if err!=nil{handleErr(w,err);return};holder:=sender;if status=="confirmed"{holder=receiver};a.audit(r.Context(),s,"confirm_handoff","sample",sid,true,map[string]any{"handoffId":in.HandoffID,"side":in.ConfirmationSide,"status":status,"currentHolderId":holder});data(w,201,map[string]any{"handoffId":in.HandoffID,"status":status,"senderConfirmed":sc,"receiverConfirmed":rc,"currentHolderId":holder})}

func (a *App) handlingCheckpoint(w http.ResponseWriter,r *http.Request,s *Session){var in struct{SampleID,AssignmentID,LocationID,ContainerType,RecordedAt,IdempotencyKey string;ObservedTemperatureC float64 `json:"observedTemperatureC"`};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if in.IdempotencyKey==""{fail(w,400,"idempotency_required","idempotencyKey is required");return};at,err:=parseTime(in.RecordedAt);if err!=nil{handleErr(w,err);return};var holder,container,status string;var tmin,tmax float64;err=a.db.QueryRowContext(r.Context(),`SELECT COALESCE(current_holder_id::text,''),container_type,temperature_min_c,temperature_max_c,status FROM lablogix.samples WHERE id=$1`,in.SampleID).Scan(&holder,&container,&tmin,&tmax,&status);if err==sql.ErrNoRows{fail(w,404,"not_found","sample not found");return};if holder!=s.UserID{fail(w,409,"custody_required","only the current holder may record a checkpoint");return};compliant:=in.ContainerType==container&&in.ObservedTemperatureC>=tmin&&in.ObservedTemperatureC<=tmax;id:=uuid();_,err=a.db.ExecContext(r.Context(),`INSERT INTO lablogix.handling_checkpoints(id,sample_id,assignment_id,holder_id,location_id,container_type,observed_temperature_c,compliant,recorded_at) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)`,id,in.SampleID,in.AssignmentID,s.UserID,nullable(in.LocationID),in.ContainerType,in.ObservedTemperatureC,compliant,at);if err!=nil{handleErr(w,err);return};if !compliant{status="exception";ex:=map[string]any{"kind":"handling_noncompliant","containerType":in.ContainerType,"observedTemperatureC":in.ObservedTemperatureC,"recordedAt":timeText(at)};_,_=a.db.ExecContext(r.Context(),`UPDATE lablogix.samples SET status='exception',exception=$2 WHERE id=$1`,in.SampleID,jsonBytes(ex));_,_=a.db.ExecContext(r.Context(),`INSERT INTO lablogix.sample_exceptions(id,sample_id,reason,kind,observed_at) VALUES($1,$2,$3,'handling_noncompliant',$4)`,uuid(),in.SampleID,"Observed handling outside sample requirements",at)};a.audit(r.Context(),s,"r