ecord_handling_checkpoint","sample",in.SampleID,true,map[string]any{"checkpointId":id,"compliant":compliant});data(w,201,map[string]any{"checkpointId":id,"sampleId":in.SampleID,"compliant":compliant,"sampleStatus":status})}

