func (a *App) labException(w http.ResponseWriter,r *http.Request,s *Session){if !requireRole(w,s,"laboratory_team"){return};var in struct{SampleID,LaboratoryID,Reason,ObservedAt,IdempotencyKey string};if err:=decode(r,&in);err!=nil{handleErr(w,err);return};if in.IdempotencyKey==""{fail(w,400,"idempotency_required","idempotencyKey is required");return};if s.AssignedLocationID!=in.LaboratoryID{fail(w,403,"forbidden","operator is not assigned to this laboratory");return};at,err:=parseTime(in.ObservedAt);if err!=nil{handleErr(w,err);return};id:=uuid();ex:=map[string]any{"exceptionId":id,"reason":in.Reason,"laboratoryId":in.LaboratoryID,"observedAt":timeText(at)};_,err=a.db.ExecContext(r.Context(),`INSERT INTO lablogix.sample_exceptions(id,sample_id,laboratory_id,reason,kind,observed_at) VALUES($1,$2,$3,$4,'laboratory_rejection',$5); UPDATE lablogix.samples SET status='exception',exception=$6 WHERE id=$2`,id,in.SampleID,in.LaboratoryID,in.Reason,at,jsonBytes(ex));if err!=nil{handleErr(w,err);return};a.audit(r.Context(),s,"record_laboratory_exception","sample",in.SampleID,true,ex);data(w,201,map[string]any{"exceptionId":id,"sampleId":in.SampleID,"status":"exception","reason":in.Reason})}

func releaseSample(tx *sql.Tx,ctx context.Context,sample string)error{rows,e:=tx.QueryContext(ctx,`SELECT id,resource_id,cooled,units FROM lablogix.capacity_reservations WHERE sample_id=$1 AND active FOR UPDATE`,sample);if e!=nil{return e};type x struct{id,r string;c bool;u int};all:=[]x{};for rows.Next(){var v x;_ =rows.Scan(&v.id,&v.r,&v.c,&v.u);all=append(all,v)};rows.Close();for _,v:=range all{col:="reserved_units";if v.c{col="cooled_reserved_units"};if _,e=tx.ExecContext(ctx,`UPDATE lablogix.capacities SET `+col+`=GREATEST(0,`+col+`-$2) WHERE resource_id=$1`,v.r,v.u);e!=nil{return e};if _,e=tx.ExecContext(ctx,`UPDATE lablogix.capacity_reservations SET active=false WHERE id=$1`,v.id);e!=nil{return e}};return nil}

