Id"]=to.String};if worker.Valid{m["workerId"]=worker.String;assigned=append(assigned,worker.String)};legs=append(legs,m);switch kind{case"collection":collections=append(collections,aid);case"node":nodes=append(nodes,aid);case"laboratory":labs=append(labs,aid)}};rows.Close()};used:=0;_ =a.db.QueryRowContext(ctx,`SELECT COALESCE(sum(units),0) FROM lablogix.capacity_reservations WHERE journey_id=$1 AND active`,id).Scan(&used);m:=map[string]any{"journeyId":id,"planVersion":version,"routeMode":mode,"status":status,"totalCostUnits":cost,"capacityUsed":used,"capacityAvailable":0,"sampleIds":ids,"orderedStops":stops,"legs":legs,"assignedWorkerIds":assigned,"collectionAssignmentIds":collections,"nodeAssignmentIds":nodes,"laboratoryAssignmentIds":labs};if parent.Valid{m["parentJourneyId"]=parent.String};if est.Valid{m["estimatedDeliveryAt"]=timeText(est.Time)};if len(collections)>0{m["collectionAssignmentId"]=collections[0]};trans:=[]string{};for _,l:=range legs{var kind string;_ =a.db.QueryRowContext(ctx,`SELECT kind FROM lablogix.assignments WHERE id=$1`,l["assignmentId"]).Scan(&kind);if kind=="transport"{trans=append(trans,l["assignmentId"].(string))}};if len(trans)>0{m["firstTransportAssignmentId"]=trans[0];m["finalTransportAssignmentId"]=trans[len(trans)-1]};if len(trans)>2{m["middleTransportAssignmentId"]=trans[1]};return m,nil}

