func (a *App) journeyPlan(ctx context.Context,id string)(map[string]any,error){var parent sql.NullString;var version int;var mode,status string;var est sql.NullTime;var cost float64;err:=a.db.QueryRowContext(ctx,`SELECT parent_journey_id,plan_version,route_mode,status,estimated_delivery_at,total_cost_units FROM lablogix.journeys WHERE id=$1`,id).Scan(&parent,&version,&mode,&status,&est,&cost);if err!=nil{return nil,err};ids:=[]string{};rows,_:=a.db.QueryContext(ctx,`SELECT sample_id FROM lablogix.journey_samples WHERE journey_id=$1 ORDER BY sample_id`,id);if rows!=nil{for rows.Next(){var x string;_=rows.Scan(&x);ids=append(ids,x)};rows.Close()};stops:=[]map[string]any{};rows,_=a.db.QueryContext(ctx,`SELECT s.id,s.location_id,s.stop_type,s.sequence,s.estimated_at,s.dwell_minutes,s.latitude,s.longitude,s.completed_at FROM lablogix.journey_stops s WHERE journey_id=$1 ORDER BY sequence`,id);if rows!=nil{for rows.Next(){var sid,lid,typ string;var seq,dwell int;var at time.Time;var lat,lon sql.NullFloat64;var done sql.NullTime;_=rows.Scan(&sid,&lid,&typ,&seq,&at,&dwell,&lat,&lon,&done);m:=map[string]any{"stopId":sid,"locationId":lid,"stopType":typ,"sequence":seq,"estimatedAt":timeText(at),"dwellMinutes":dwell};if lat.Valid&&lon.Valid{m["coordinate"]=coordinate{lat.Float64,lon.Float64}};if done.Valid{m["completedAt"]=timeText(done.Time)};stops=append(stops,m)};rows.Close()};legs:=[]map[string]any{};assigned:=[]string{};collections,nodes,labs:=[]string{},[]string{},[]string{};rows,_=a.db.QueryContext(ctx,`SELECT id,sequence,status,from_location_id,to_location_id,worker_id,sample_id,kind FROM lablogix.assignments WHERE journey_id=$1 ORDER BY sequence,id`,id);if rows!=nil{for rows.Next(){var aid,status,sid,kind string;var seq int;var from,to,worker sql.NullString;_=rows.Scan(&aid,&seq,&status,&from,&to,&worker,&sid,&kind);m:=map[string]any{"assignmentId":aid,"sequence":seq,"status":status,"sampleId":sid};if from.Valid{m["fromLocationId"]=from.String};if to.Valid{m["toLocation