func (a *App) replaceJourney(ctx context.Context,old string,expected int)(string,error){newID:=uuid();err:=a.transaction(ctx,func(tx *sql.Tx)error{var ver int;var mode,status string;var est sql.NullTime;var cost float64;var active bool;if e:=tx.QueryRowContext(ctx,`SELECT plan_version,route_mode,status,estimated_delivery_at,total_cost_units,active FROM lablogix.journeys WHERE id=$1 FOR UPDATE`,old).Scan(&ver,&mode,&status,&est,&cost,&active);e!=nil{return e};if !active{return asError("inactive_plan","journey is inactive",409)};if ver!=expected{return asError("stale_plan","plan version has changed",409)};if _,e:=tx.ExecContext(ctx,`INSERT INTO lablogix.journeys(id,parent_journey_id,plan_version,route_mode,status,estimated_delivery_at,total_cost_units) VALUES($1,$2,$3,$4,'planned',$5,$6)`,newID,old,ver+1,mode,est,cost);e!=nil{return e};if _,e:=tx.ExecContext(ctx,`INSERT INTO lablogix.journey_samples SELECT $1,sample_id FROM lablogix.journey_samples WHERE journey_id=$2; INSERT INTO lablogix.journey_stops(id,journey_id,location_id,stop_type,sequence,estimated_at,dwell_minutes,latitude,longitude,completed_at) SELECT CASE WHEN completed_at IS NULL THEN $3::uuid ELSE id END,$1,location_id,stop_type,sequence,estimated_at,dwell_minutes,latitude,longitude,completed_at FROM lablogix.journey_stops WHERE journey_id=$2`,newID,old,uuid());e!=nil{return e};rows,e:=tx.QueryContext(ctx,`SELECT sample_id,kind,sequence,from_location_id,to_location_id,node_id,laboratory_id,offered_worker_id,worker_id,status,offer_expires_at,completed_at,id FROM lablogix.assignments WHERE journey_id=$1 ORDER BY sequence`,old);if e!=nil{return e};defer rows.Close();for rows.Next(){var sid,kind,status,id string;var seq int;var from,to,node,lab,offered,worker sql.NullString;var expiry,done sql.NullTime;_ =rows.Scan(&sid,&kind,&seq,&from,&to,&node,&lab,&offered,&worker,&status,&expiry,&done,&id);if done.Valid||status=="completed"{continue};if _,e=tx.ExecContext(ctx,`INSERT INTO lablogix.assignments(id,journe