.login-layout{min-height:100vh;display:grid;grid-template-columns:minmax(380px,46%) 1fr}.login-story{background:linear-gradient(145deg,#0d2b23,#123b31 67%,#0d3129);color:#fff;padding:42px 9%;display:flex;flex-direction:column;position:relative;overflow:hidden}.login-story:after{content:"";position:absolute;width:560px;height:560px;border:1px solid rgba(139,210,188,.14);border-radius:50%;right:-250px;bottom:-280px;box-shadow:0 0 0 70px rgba(139,210,188,.03),0 0 0 150px rgba(139,210,188,.02)}.story-copy{margin:auto 0;position:relative;z-index:1}.story-copy h1{font-size:clamp(42px,5vw,72px);line-height:1.02;margin:18px 0 28px;font-weight:680}.story-copy h1 em{font-family:Georgia,serif;font-weight:400;color:#98dac5}.story-copy p{color:#bfd1ca;line-height:1.65;max-width:450px;font-size:17px}.story-foot{font-size:12px;color:#89a49a;margin:0;letter-spacing:.04em}.route-art{position:absolute;right:8%;top:20%;height:55%;width:34%;border-right:1px dashed rgba(151,218,197,.25);transform:rotate(13deg)}.route-dot{position:absolute;width:11px;height:11px;border:3px solid #8ed3bd;border-radius:50%;background:#123b31;right:-6px}.route-dot.a{top:5%}.route-dot.b{top:45%}.route-dot.c{bottom:3%}.login-panel{display:grid;place-items:center;padding:32px;background:#f7f8f5}.login-card{width:min(410px,100%)}.login-card h2{font-size:36px;margin:12px 0 8px}.login-card>p{color:var(--muted);margin-bottom:34px}.login-card label,.stack-form label,.form-panel label,.inline-form label{display:grid;gap:8px;font-size:13px;font-weight:700;color:#2b3d36;margin-bottom:18px}.login-card input,.stack-form input,.stack-form select,.form-panel input,.form-panel select,.inline-form input,.searchbar input{width:100%;border:1px solid #cfd9d3;border-radius:8px;padding:13px 14px;background:#fff;color:var(--ink);outline:none;transition:.2s}.login-card input:focus,.stack-form input:focus,.form-panel input:focus,.form-panel select:focus,.searchbar input:focus{border-color:var(--green);box-shadow:0 0 0 3px rgba(10,1