import { FormEvent, useEffect, useMemo, useRef, useState } from 'react'
import maplibregl, { Map as MapLibreMap, Marker } from 'maplibre-gl'
import { Protocol } from 'pmtiles'

type Bootstrap = { user: { userId: string; username: string; fullName?: string; roles: string[]; activeRole: string; roleSelectionRequired: boolean }; serverTime: string; requesterSamples?: any[]; operations?: any }
type Notice = { kind: 'success' | 'error' | 'info'; text: string }

const sampleTypes = [
  { id: '10000000-0000-4000-8000-000000000001', name: 'Amber', container: 'standard vial', min: 15, max: 25 },
  { id: '10000000-0000-4000-8000-000000000002', name: 'Indigo', container: 'light-safe vial', min: 15, max: 25 },
  { id: '10000000-0000-4000-8000-000000000003', name: 'Frost', container: 'cooled carrier', min: 2, max: 8 },
  { id: '10000000-0000-4000-8000-000000000004', name: 'Pulse', container: 'priority vial', min: 15, max: 25 },
]
const roleNames: Record<string, string> = { administrator: 'Administrator', dispatcher: 'Dispatcher', requester: 'Requester', collection_professional: 'Collection professional', delivery_partner: 'Relay courier', node_handler: 'Node handler', laboratory_team: 'Laboratory intake' }
const isOps = (role: string) => role === 'administrator' || role === 'dispatcher'
const fmt = (v?: string) => v ? new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(v)) : '—'
const uid = () => crypto.randomUUID()

async function api(path: string, options: RequestInit = {}) {
  const token = localStorage.getItem('lablogix_token')
  const res = await fetch(path, { ...options, headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(options.headers || {}) } })
  const body = await res.json().catch(() => ({ error: 'The server returned an unreadable response.' }))
  if (!res.ok) throw new Error(body.error || body.code || `Request failed (${res.status})`)
  return body.data ?? body
}

export default function App() {
  const [boot, setBoot] = useState<Bootstrap | null>(null)
  const [loading, setLoading] = useState(Boolean(localStorage.getItem('lablogix_token')))
  const [notice, setNotice] = useState<Notice | null>(null)
  const [page, setPage] = useState('overview')
  const load = async () => { setLoading(true); try { setBoot(await api('/api/ui/bootstrap')); setNotice(null) } catch { localStorage.removeItem('lablogix_token'); setBoot(null) } finally { setLoading(false) } }
  useEffect(() => { if (localStorage.getItem('lablogix_token')) load(); else setLoading(false) }, [])
  const signOut = () => { localStorage.removeItem('lablogix_token'); setBoot(null); setPage('overview'); setNotice(null) }
  if (loading) return <div className="center-screen"><div className="spinner" /><p>Preparing custody workspace…</p></div>
  if (!boot) return <Login onLogin={load} />
  const role = boot.user.activeRole
  if (boot.user.roleSelectionRequired || !role) return <RoleGate boot={boot} onSelected={load} onSignOut={signOut} />
  return <Shell boot={boot} page={page} setPage={setPage} refresh={load} signOut={signOut} notice={notice} setNotice={setNotice} />
}

function Login({ onLogin }: { onLogin: () => Promise<void> }) {
  const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false)
  const submit = async (e: FormEvent) => { e.preventDefault(); setBusy(true); setError(''); try { const data = await api('/api/authenticate-user', { method: 'POST', body: JSON.stringify({ username, password }) }); localStorage.setItem('lablogix_token', data.sessionToken); await onLogin() } catch (e) { setError(e instanceof Error ? e.message : 'Sign in failed') } finally { setBusy(false) } }
  return <main className="login-layout">
    <section className="login-story"><div className="brand brand-light"><Logo /> <span>LabLogix</span></div><div className="story-copy"><span className="eyebrow pale">Chain of custody, clearly connected</span><h1>Every sample.<br />Every handoff.<br /><em>On time.</em></h1><p>One operations workspace from collection window to verified laboratory receipt.</p></div><div className="route-art"><span className="route-dot a" /><span className="route-dot b" /><span className="route-dot c" /></div><p className="story-foot">Secure clinical logistics · Live network awareness</p></section>
    <section className="login-panel"><form className="login-card" onSubmit={submit}><span className="eyebrow">Operations access</span><h2>Welcome back</h2><p>Sign in to continue to your assigned workspace.</p>{error && <div role="alert" className="alert error">{error}</div>}<label>Username<input aria-label="Username" value={username} onChange={e => setUsername(e.target.value)} autoComplete="username" required /></label><label>Password<input aria-label="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} autoComplete="current-password" required /></label><button className="primary wide" disabled={busy}>{busy ? 'Signing in…' : 'Sign in securely'} <span>→</span></button><small>Access is logged and restricted by your active role.</small></form></section>
  </main>
}

function RoleGate({ boot, onSelected, onSignOut }: { boot: Bootstrap; onSelected: () => Promise<void>; onSignOut: () => void }) {
  const choose = async (role: string) => { await api('/api/select-active-role', { method: 'POST', body: JSON.stringify({ role }) }); await onSelected() }
  return <main className="role-gate"><div className="brand"><Logo /><span>LabLogix</span></div><section className="role-card"><span className="eyebrow">Role context required</span><h1>What are you working on?</h1><p>Choose a role for this session. Switching context never changes your account access.</p><div className="role-grid">{boot.user.roles.map(r => <button key={r} onClick={() => choose(r)}><span className="role-icon">{roleIcon(r)}</span><strong>{roleNames[r] || r}</strong><small>Open role workspace</small></button>)}</div><button className="text-button" onClick={onSignOut}>Sign out</button></section></main>
}

function Shell({ boot, page, setPage, refresh, signOut, notice, setNotice }: { boot: Bootstrap; page: string; setPage: (p: string) => void; refresh: () => Promise<void>; signOut: () => void; notice: Notice | null; setNotice: (n: Notice | null) => void }) {
  const role = boot.user.activeRole
  const nav = [{ id: 'overview', label: 'Overview', icon: '⌂' }, { id: 'work', label: 'My work', icon: '◫' }]
  if (role === 'requester') nav.push({ id: 'request', label: 'New request', icon: '+' })
  if (isOps(role)) nav.push({ id: 'network', label: 'Network monitor', icon: '⌘' }, { id: 'audit', label: 'Audit trail', icon: '≡' })
  if (['node_handler', 'laboratory_team', 'administrator'].includes(role)) nav.push({ id: 'capacity', label: 'Capacity', icon: '▥' })
  if (role === 'administrator') nav.push({ id: 'admin', label: 'Administration', icon: '⚙' })
  const switchRole = async (value: string) => { await api('/api/select-active-role', { method: 'POST', body: JSON.stringify({ role: value }) }); setPage('overview'); await refresh() }
  return <div className="app-shell"><aside><div className="brand brand-light"><Logo /><span>LabLogix</span></div><div className="context-label">Working as</div><label className="role-select"><span className="sr-only">Working role</span><select aria-label="Working role" value={role} onChange={e => switchRole(e.target.value)}>{boot.user.roles.map(r => <option key={r} value={r}>{roleNames[r] || r}</option>)}</select></label><nav aria-label="Primary navigation">{nav.map(n => <button key={n.id} className={page === n.id ? 'active' : ''} aria-current={page === n.id ? 'page' : undefined} onClick={() => { setPage(n.id); setNotice(null) }}><span>{n.icon}</span>{n.label}</button>)}</nav><div className="side-status"><span className="pulse" /><div><strong>Network connected</strong><small>Secure session</small></div></div><button className="signout" onClick={signOut}>↪ <span>Sign out</span></button></aside><main className="workspace"><header><div><span className="eyebrow">{roleNames[role]} workspace</span><h1>{pageTitle(page)}</h1></div><div className="user-chip"><span>{initials(boot.user.fullName || boot.user.username)}</span><div><strong>{boot.user.fullName || boot.user.username}</strong><small>{roleNames[role]}</small></div></div></header>{notice && <div role={notice.kind === 'error' ? 'alert' : 'status'} className={`alert ${notice.kind}`}>{notice.text}<button aria-label="Dismiss message" onClick={() => setNotice(null)}>×</button></div>}<div className="page-content">
    {page === 'overview' && <Overview boot={boot} />}
    {page === 'work' && <Work role={role} setNotice={setNotice} />}
    {page === 'request' && <RequestForm setNotice={setNotice} onCreated={() => setPage('work')} />}
    {page === 'network' && <Network />}
