package main

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"strings"
	"time"

	"github.com/lib/pq"
	"golang.org/x/crypto/bcrypt"
)

type certification struct {
	Code      string `json:"code"`
	Active    bool   `json:"active"`
	ExpiresAt string `json:"expiresAt,omitempty"`
}

func (a *App) authenticate(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := decode(r, &in); err != nil {
		handleErr(w, err)
		return
	}
	var id, hash string
	var roles pq.StringArray
	var active bool
	err := a.db.QueryRowContext(r.Context(), `SELECT id,password_hash,roles,active FROM lablogix.users WHERE username=$1`, in.Username).Scan(&id, &hash, &roles, &active)
	if err != nil || !active || bcrypt.CompareHashAndPassword([]byte(hash), []byte(in.Password)) != nil {
		a.audit(r.Context(), nil, "sign_in", "user", in.Username, false, map[string]any{"outcome": "invalid_credentials"})
		fail(w, 401, "invalid_credentials", "invalid username or password")
		return
	}
	activeRole := ""
	if len(roles) == 1 {
		activeRole = roles[0]
	}
	t := token()
	_, err = a.db.ExecContext(r.Context(), `INSERT INTO lablogix.sessions(token,user_id,active_role,expires_at) VALUES($1,$2,$3,$4)`, t, id, activeRole, time.Now().Add(24*time.Hour))
	if err != nil {
		handleErr(w, err)
		return
	}
	s := &Session{UserID: id, ActiveRole: activeRole}
	a.audit(r.Context(), s, "sign_in", "user", id, true, map[string]any{"username": in.Username})
	data(w, 200, map[string]any{"sessionToken": t, "userId": id, "roles": []string(roles), "activeRole": activeRole})
}

func (a *App) selectRole(w http.ResponseWriter, r *http.Request, s *Session) {
	if r.Method != http.MethodPost {
		fail(w, 405, "method_not_allowed", "method not allowed")
		return
	}
	var in struct {
		Role string `json:"role"`
	}
	if err := decode(r, &in); err != nil {
		handleErr(w, err)
		return
	}
	if !contains(s.Roles, in.Role) {
		fail(w, 403, "forbidden", "role is not assigned to this account")
		return
	}
	if _, err := a.db.ExecContext(r.Context(), `UPDATE lablogix.sessions SET active_role=$1 WHERE token=$2`, in.Role, s.Token); err != nil {
		handleErr(w, err)
