func userResponse(id, username, email, fullName, phone string, roles, quals []string, certs []certification, active bool) map[string]any {
	m := map[string]any{"userId": id, "username": username, "roles": roles, "qualifications": quals, "certifications": certs, "active": active}
	if email != "" {
		m["email"] = email
	}
	if fullName != "" {
		m["fullName"] = fullName
	}
	if phone != "" {
		m["phone"] = phone
	}
	return m
}

