		return
	}
	_, _ = a.db.ExecContext(r.Context(), `UPDATE lablogix.sessions SET active_role='' WHERE user_id=$1 AND NOT(active_role=ANY($2))`, in.UserID, pq.Array(in.Roles))
	a.audit(r.Context(), s, "update_user_access", "user", in.UserID, true, map[string]any{"roles": in.Roles, "active": in.Active})
	data(w, 201, map[string]any{"userId": in.UserID, "roles": in.Roles, "qualifications": nilSlice(in.Qualifications), "certifications": certMaps(in.Certifications), "active": in.Active})
}
func nilSlice(v []string) []string {
	if v == nil {
