   340			if _, e = tx.ExecContext(ctx, `UPDATE lablogix.journeys SET active=false,status='replaced',replacement_journey_id=$2 WHERE id=$1`, old, newID); e != nil {
   341				return e
   342			}
   343			if _, e = tx.ExecContext(ctx, `UPDATE lablogix.assignments SET status='cancelled' WHERE journey_id=$1 AND status<>'completed'`, old); e != nil {
   344				return e
