   357	func (a *App) reportDisruption(w http.ResponseWriter, r *http.Request, s *Session) {
   358		if !requireRole(w, s, "administrator", "dispatcher") {
   359			return
   360		}
   361		var in struct{ ResourceType, ResourceID, Reason, OccurredAt, IdempotencyKey string }
   362		if err := decode(r, &in); err != nil {
   363			handleErr(w, err)
   364			return
   365		}
   366		if in.IdempotencyKey == "" {
   367			fail(w, 400, "idempotency_required", "idempotencyKey is required")
   368			return
   369		}
   370		if _, err := parseTime(in.OccurredAt); err != nil {
   371			handleErr(w, err)
   372			return
   373		}
   374		journeys := []struct {
   375			id  string
   376			ver int
   377		}{}
   378		q := `SELECT DISTINCT j.id,j.plan_version FROM lablogix.journeys j JOIN lablogix.capacity_reservations r ON r.journey_id=j.id WHERE j.active AND r.active AND r.resource_id=$1`
   379		if in.ResourceType == "worker" {
   380			q = `SELECT DISTINCT j.id,j.plan_version FROM lablogix.journeys j JOIN lablogix.assignments a ON a.journey_id=j.id WHERE j.active AND (a.worker_id=$1 OR a.offered_worker_id=$1) AND a.status<>'completed'`
   381		}
   382		rows, _ := a.db.QueryContext(r.Context(), q, in.ResourceID)
   383		if rows != nil {
   384			for rows.Next() {
   385				var x struct {
   386					id  string
   387					ver int
   388				}
   389				_ = rows.Scan(&x.id, &x.ver)
   390				journeys = append(journeys, x)
   391			}
   392			rows.Close()
   393		}
   394		samples, repls := []string{}, []string{}
   395		for _, j := range journeys {
   396			newID, e := a.replaceJourney(r.Context(), j.id, j.ver)
   397			if e == nil {
   398				repls = append(repls, newID)
   399				rs, _ := a.db.QueryContext(r.Context(), `SELECT sample_id FROM lablogix.journey_samples WHERE journey_id=$1`, newID)
   400				if rs != nil {
   401					for rs.Next() {
   402						var id string
   403						_ = rs.Scan(&id)
   404						samples = append(samples, id)
   405					}
   406					rs.Close()
   407				}
   408			}
   409		}
   410		status := "not_required"
   411		if len(repls) > 0 {
   412			status = "replaced"
   413		}
   414		id := uuid()
   415		a.audit(r.Context(), s, "report_disruption", in.ResourceType, in.ResourceID, true, map[string]any{"disruptionId": id, "reason": in.Reason, "replacementPlanIds": repls})
   416		data(w, 201, map[string]any{"disruptionId": id, "affectedSampleIds": samples, "replacementPlanIds": repls, "replanStatus": status})
   417	}
