			return e
		}
		rows, e := tx.QueryContext(ctx, `SELECT sample_id,kind,sequence,from_location_id,to_location_id,node_id,laboratory_id,offered_worker_id,worker_id,status,offer_expires_at,completed_at,id FROM lablogix.assignments WHERE journey_id=$1 ORDER BY sequence`, old)
		if e != nil {
			return e
		}
		defer rows.Close()
		for rows.Next() {
			var sid, kind, status, id string
			var seq int
			var from, to, node, lab, offered, worker sql.NullString
			var expiry, done sql.NullTime
			_ = rows.Scan(&sid, &kind, &seq, &from, &to, &node, &lab, &offered, &worker, &status, &expiry, &done, &id)
