				return e
			}
		}
		if _, e = tx.ExecContext(ctx, `UPDATE lablogix.journeys SET active=false,status='replaced',replacement_journey_id=$2 WHERE id=$1`, old, newID); e != nil {
			return e
		}
		if _, e = tx.ExecContext(ctx, `UPDATE lablogix.assignments SET status='cancelled' WHERE journey_id=$1 AND status<>'completed'`, old); e != nil {
			return e
		}
		if _, e = tx.ExecContext(ctx, `UPDATE lablogix.samples SET active_journey_id=$2 WHERE active_journey_id=$1`, old, newID); e != nil {
			return e
		}
		if _, e = tx.ExecContext(ctx, `UPDATE lablogix.capacity_reservations SET journey_id=$2 WHERE journey_id=$1 AND active`, old, newID); e != nil {
			return e
		}
		return nil
	})
	return newID, err
}

func (a *App) reportDisruption(w http.ResponseWriter, r *http.Request, s *Session) {
	if !requireRole(w, s, "administrator", "dispatcher") {
		return
	}
	var in struct{ ResourceType, ResourceID, Reason, OccurredAt, IdempotencyKey string }
	if err := decode(r, &in); err != nil {
		handleErr(w, err)
		return
	}
	if in.IdempotencyKey == "" {
		fail(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	if _, err := parseTime(in.OccurredAt); err != nil {
		handleErr(w, err)
		return
	}
	journeys := []struct {
		id  string
		ver int
	}{}
	q := `SELECT DISTINCT j.id,j.plan_version FROM lablogix.journeys j JOIN lablogix.capacity_reservations r ON r.journey_id=j.id WHERE j.active AND r.active AND r.resource_id=$1`
	if in.ResourceType == "worker" {
		q = `SELECT DISTINCT j.id,j.plan_version FROM lablogix.journeys j JOIN lablogix.assignments a ON a.journey_id=j.id WHERE j.active AND (a.worker_id=$1 OR a.offered_worker_id=$1) AND a.status<>'completed'`
	}
	rows, _ := a.db.QueryContext(r.Context(), q, in.ResourceID)
	if rows != nil {
		for rows.Next() {
			var x struct {
				id  string
				ver int
			}
			_ = rows.Scan(&x.id, &x.ver)
			journeys = append(journeys, x)
		}
		rows.Close()
	}
	samples, repls := []string{}, []string{}
	for _, j := range journeys {
		newID, e := a.replaceJourney(r.Context(), j.id, j.ver)
		if e == nil {
			repls = append(repls, newID)
			rs, _ := a.db.QueryContext(r.Context(), `SELECT sample_id FROM lablogix.journey_samples WHERE journey_id=$1`, newID)
			if rs != nil {
				for rs.Next() {
					var id string
					_ = rs.Scan(&id)
					samples = append(samples, id)
				}
				rs.Close()
			}
		}
	}
	status := "not_required"
	if len(repls) > 0 {
		status = "replaced"
	}
	id := uuid()
	a.audit(r.Context(), s, "report_disruption", in.ResourceType, in.ResourceID, true, map[string]any{"disruptionId": id, "reason": in.Reason, "replacementPlanIds": repls})
	data(w, 201, map[string]any{"disruptionId": id, "affectedSampleIds": samples, "replacementPlanIds": repls, "replanStatus": status})
}

func (a *App) editPlan(w http.ResponseWriter, r *http.Request, s *Session) {
	if !requireRole(w, s, "administrator", "dispatcher") {
		return
	}
	var in struct {
		JourneyID           string         `json:"journeyId"`
		ExpectedPlanVersion int            `json:"expectedPlanVersion"`
		ChangeType          string         `json:"changeType"`
		Changes             map[string]any `json:"changes"`
		IdempotencyKey      string         `json:"idempotencyKey"`
	}
	if err := decode(r, &in); err != nil {
		handleErr(w, err)
		return
	}
	if in.IdempotencyKey == "" {
		fail(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	res, err := a.db.ExecContext(r.Context(), `UPDATE lablogix.journeys SET plan_version=plan_version+1 WHERE id=$1 AND active AND plan_version=$2`, in.JourneyID, in.ExpectedPlanVersion)
	if err != nil {
		handleErr(w, err)
		return
	}
	n, _ := res.RowsAffected()
	if n == 0 {
		fail(w, 409, "stale_plan", "plan version has changed or is inactive")
		return
	}
	a.audit(r.Context(), s, "edit_active_plan", "journey", in.JourneyID, true, map[string]any{"changeType": in.ChangeType, "changes": in.Changes})
	plan, err := a.journeyPlan(r.Context(), in.JourneyID)
	if err != nil {
		handleErr(w, err)
		return
	}
	data(w, 201, plan)
}

func (a *App) splitJourney(w http.ResponseWriter, r *http.Request, s *Session) {
	if !requireRole(w, s, "administrator", "dispatcher") {
		return
	}
	var in struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := decode(r, &in); err != nil {
		handleErr(w, err)
		return
	}
	if len(in.SampleIDs) == 0 {
		fail(w, 409, "invalid_split", "sampleIds cannot be empty")
		return
	}
	newID := uuid()
	err := a.transaction(r.Context(), func(tx *sql.Tx) error {
		var ver int
		var mode string
		var est sql.NullTime
		var cost float64
		if e := tx.QueryRowContext(r.Context(), `SELECT plan_version,route_mode,estimated_delivery_at,total_cost_units FROM lablogix.journeys WHERE id=$1 AND active FOR UPDATE`, in.JourneyID).Scan(&ver, &mode, &est, &cost); e != nil {
			return e
		}
		if ver != in.ExpectedPlanVersion {
			return asError("stale_plan", "plan version changed", 409)
		}
		if _, e := tx.ExecContext(r.Context(), `INSERT INTO lablogix.journeys(id,parent_journey_id,plan_version,route_mode,status,estimated_delivery_at,total_cost_units) VALUES($1,$2,1,$3,'planned',$4,$5)`, newID, in.JourneyID, mode, est, cost); e != nil {
			return e
		}
		for _, sid := range in.SampleIDs {
			res, e := tx.ExecContext(r.Context(), `DELETE FROM lablogix.journey_samples WHERE journey_id=$1 AND sample_id=$2`, in.JourneyID, sid)
			if e != nil {
				return e
			}
			n, _ := res.RowsAffected()
			if n == 0 {
				return asError("invalid_split", "sample is not in journey", 409)
			}
			if _, e = tx.ExecContext(r.Context(), `INSERT INTO lablogix.journey_samples VALUES($1,$2)`, newID, sid); e != nil {
				return e
			}
			if _, e = tx.ExecContext(r.Context(), `UPDATE lablogix.samples SET active_journey_id=$1 WHERE id=$2`, newID, sid); e != nil {
				return e
			}
			if _, e = tx.ExecContext(r.Context(), `UPDATE lablogix.assignments SET journey_id=$1 WHERE sample_id=$2 AND status<>'completed'`, newID, sid); e != nil {
				return e
			}
			if _, e = tx.ExecContext(r.Context(), `UPDATE lablogix.capacity_reservations SET journey_id=$1 WHERE sample_id=$2 AND active`, newID, sid); e != nil {
				return e
			}
		}
		if _, e := tx.ExecContext(r.Context(), `UPDATE lablogix.journeys SET plan_version=plan_version+1 WHERE id=$1`, in.JourneyID); e != nil {
			return e
		}
		_, e := tx.ExecContext(r.Context(), `INSERT INTO lablogix.journey_stops(id,journey_id,location_id,stop_type,sequence,estimated_at,dwell_minutes,latitude,longitude) SELECT $2,$3,location_id,stop_type,sequence,estimated_at,dwell_minutes,latitude,longitude FROM lablogix.journey_stops WHERE journey_id=$1 LIMIT 1`, in.JourneyID, uuid(), newID)
		return e
	})
	if err != nil {
		handleErr(w, err)
		return
	}
	p1, _ := a.journeyPlan(r.Context(), in.JourneyID)
	p2, _ := a.journeyPlan(r.Context(), newID)
	a.audit(r.Context(), s, "split_journey", "journey", in.JourneyID, true, map[string]any{"splitJourneyId": newID, "sampleIds": in.SampleIDs})
	data(w, 201, map[string]any{"journey": p1, "splitJourney": p2})
}

func (a *App) mergeJourneys(w http.ResponseWriter, r *http.Request, s *Session) {
	if !requireRole(w, s, "administrator", "dispatcher") {
		return
	}
	var in struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := decode(r, &in); err != nil {
		handleErr(w, err)
		return
	}
	if len(in.SourceJourneyIDs) == 0 {
		fail(w, 409, "invalid_batch", "source journeys required")
		return
	}
	err := a.transaction(r.Context(), func(tx *sql.Tx) error {
		var ver int
		if e := tx.QueryRowContext(r.Context(), `SELECT plan_version FROM lablogix.journeys WHERE id=$1 AND active FOR UPDATE`, in.TargetJourneyID).Scan(&ver); e != nil {
			return e
		}
		if ver != in.ExpectedPlanVersion {
			return asError("stale_plan", "plan version changed", 409)
		}
		for _, src := range in.SourceJourneyIDs {
			if src == in.TargetJourneyID {
				return asError("invalid_batch", "cannot merge journey into itself", 409)
			}
			if _, e := tx.ExecContext(r.Context(), `INSERT INTO lablogix.journey_samples SELECT $1,sample_id FROM lablogix.journey_samples WHERE journey_id=$2 ON CONFLICT DO NOTHING`, in.TargetJourneyID, src); e != nil {
				return e
			}
			if _, e := tx.ExecContext(r.Context(), `UPDATE lablogix.samples SET active_journey_id=$1 WHERE active_journey_id=$2`, in.TargetJourneyID, src); e != nil {
				return e
			}
			if _, e := tx.ExecContext(r.Context(), `UPDATE lablogix.assignments SET journey_id=$1 WHERE journey_id=$2 AND status<>'completed'`, in.TargetJourneyID, src); e != nil {
				return e
			}
			if _, e := tx.ExecContext(r.Context(), `UPDATE lablogix.capacity_reservations SET journey_id=$1 WHERE journey_id=$2 AND active`, in.TargetJourneyID, src); e != nil {
				return e
			}
			if _, e := tx.ExecContext(r.Context(), `UPDATE lablogix.journeys SET active=false,status='merged' WHERE id=$1`, src); e != nil {
				return e
			}
		}
		_, e := tx.ExecContext(r.Context(), `UPDATE lablogix.journeys SET plan_version=plan_version+1,route_mode='batched' WHERE id=$1`, in.TargetJourneyID)
		return e
	})
	if err != nil {
		handleErr(w, err)
		return
	}
	plan, _ := a.journeyPlan(r.Context(), in.TargetJourneyID)
	a.audit(r.Context(), s, "merge_journeys", "journey", in.TargetJourneyID, true, map[string]any{"sourceJourneyIds": in.SourceJourneyIDs})
	data(w, 201, plan)
}

