package main

import (
	"context"
	"database/sql"
	"net/http"
	"time"

	"github.com/lib/pq"
)

func (a *App) readJourneyPlan(w http.ResponseWriter, r *http.Request, s *Session) {
	var in struct {
		JourneyID string `json:"journeyId"`
	}
	if err := decode(r, &in); err != nil {
		handleErr(w, err)
		return
	}
	var allowed bool
	if s.hasRole("administrator", "dispatcher") {
		allowed = true
	} else if s.ActiveRole == "requester" {
		_ = a.db.QueryRowContext(r.Context(), `SELECT EXISTS(SELECT 1 FROM lablogix.journey_samples js JOIN lablogix.samples x ON x.id=js.sample_id WHERE js.journey_id=$1 AND x.requester_id=$2)`, in.JourneyID, s.UserID).Scan(&allowed)
	} else {
		_ = a.db.QueryRowContext(r.Context(), `SELECT EXISTS(SELECT 1 FROM lablogix.assignments WHERE journey_id=$1 AND (worker_id=$2 OR offered_worker_id=$2))`, in.JourneyID, s.UserID).Scan(&allowed)
	}
	if !allowed {
		fail(w, 403, "forbidden", "journey is outside your role scope")
		return
	}
	plan, err := a.journeyPlan(r.Context(), in.JourneyID)
	if err == sql.ErrNoRows {
		fail(w, 404, "not_found", "journey not found")
		return
	}
	if err != nil {
		handleErr(w, err)
		return
	}
	if s.ActiveRole == "requester" {
		out := map[string]any{"journeyId": plan["journeyId"], "sampleIds": plan["sampleIds"], "legs": publicLegs(plan["legs"])}
		for _, k := range []string{"parentJourneyId", "planVersion", "routeMode", "status", "estimatedDeliveryAt", "totalCostUnits", "orderedStops"} {
			if v, ok := plan[k]; ok {
				out[k] = v
			}
		}
		data(w, 200, out)
		return
	}
	if !s.hasRole("administrator", "dispatcher") {
		legs := []map[string]any{}
		ids := []string{}
		for _, raw := range plan["legs"].([]map[string]any) {
			if raw["workerId"] == s.UserID {
				legs = append(legs, raw)
				ids = append(ids, raw["assignmentId"].(string))
			}
		}
		out := map[string]any{"journeyId": plan["journeyId"], "planVersion": plan["planVersion"], "routeMode": plan["routeMode"], "status": plan["status"], "scope": "assigned_legs", "assignmentIds": ids, "legs": legs, "orderedStops": plan["orderedStops"]}
		if v, ok := plan["parentJourneyId"]; ok {
			out["parentJourneyId"] = v
		}
		if v, ok := plan["estimatedDeliveryAt"]; ok {
			out["estimatedDeliveryAt"] = v
		}
		out["sampleIds"] = plan["sampleIds"]
		data(w, 200, out)
		return
	}
	data(w, 200, plan)
}
func publicLegs(v any) []map[string]any {
	out := []map[string]any{}
	for _, x := range v.([]map[string]any) {
		m := map[string]any{"sequence": x["sequence"], "status": x["status"]}
		if y, ok := x["fromLocationId"]; ok {
			m["fromLocationId"] = y
		}
		if y, ok := x["toLocationId"]; ok {
			m["toLocationId"] = y
		}
		out = append(out, m)
	}
	return out
}
func (a *App) journeyPlan(ctx context.Context, id string) (map[string]any, error) {
	var parent sql.NullString
	var version int
	var mode, status string
	var est sql.NullTime
	var cost float64
	err := a.db.QueryRowContext(ctx, `SELECT parent_journey_id,plan_version,route_mode,status,estimated_delivery_at,total_cost_units FROM lablogix.journeys WHERE id=$1`, id).Scan(&parent, &version, &mode, &status, &est, &cost)
	if err != nil {
		return nil, err
	}
	ids := []string{}
	rows, _ := a.db.QueryContext(ctx, `SELECT sample_id FROM lablogix.journey_samples WHERE journey_id=$1 ORDER BY sample_id`, id)
	if rows != nil {
		for rows.Next() {
			var x string
			_ = rows.Scan(&x)
			ids = append(ids, x)
		}
		rows.Close()
	}
	stops := []map[string]any{}
	rows, _ = a.db.QueryContext(ctx, `SELECT s.id,s.location_id,s.stop_type,s.sequence,s.estimated_at,s.dwell_minutes,s.latitude,s.longitude,s.completed_at FROM lablogix.journey_stops s WHERE journey_id=$1 ORDER BY sequence`, id)
	if rows != nil {
		for rows.Next() {
			var sid, lid, typ string
			var seq, dwell int
			var at time.Time
			var lat, lon sql.NullFloat64
			var done sql.NullTime
			_ = rows.Scan(&sid, &lid, &typ, &seq, &at, &dwell, &lat, &lon, &done)
			m := map[string]any{"stopId": sid, "locationId": lid, "stopType": typ, "sequence": seq, "estimatedAt": timeText(at), "dwellMinutes": dwell}
			if lat.Valid && lon.Valid {
				m["coordinate"] = coordinate{lat.Float64, lon.Float64}
			}
			if done.Valid {
				m["completedAt"] = timeText(done.Time)
			}
			stops = append(stops, m)
		}
		rows.Close()
	}
	legs := []map[string]any{}
	assigned := []string{}
	collections, nodes, labs := []string{}, []string{}, []string{}
	rows, _ = a.db.QueryContext(ctx, `SELECT id,sequence,status,from_location_id,to_location_id,worker_id,sample_id,kind FROM lablogix.assignments WHERE journey_id=$1 ORDER BY sequence,id`, id)
	if rows != nil {
		for rows.Next() {
			var aid, status, sid, kind string
			var seq int
			var from, to, worker sql.NullString
			_ = rows.Scan(&aid, &seq, &status, &from, &to, &worker, &sid, &kind)
			m := map[string]any{"assignmentId": aid, "sequence": seq, "status": status, "sampleId": sid}
			if from.Valid {
				m["fromLocationId"] = from.String
			}
			if to.Valid {
				m["toLocationId"] = to.String
			}
			if worker.Valid {
				m["workerId"] = worker.String
				assigned = append(assigned, worker.String)
			}
			legs = append(legs, m)
			switch kind {
			case "collection":
				collections = append(collections, aid)
			case "node":
				nodes = append(nodes, aid)
			case "laboratory":
				labs = append(labs, aid)
			}
		}
		rows.Close()
	}
	used := 0
	_ = a.db.QueryRowContext(ctx, `SELECT COALESCE(sum(units),0) FROM lablogix.capacity_reservations WHERE journey_id=$1 AND active`, id).Scan(&used)
	m := map[string]any{"journeyId": id, "planVersion": version, "routeMode": mode, "status": status, "totalCostUnits": cost, "capacityUsed": used, "capacityAvailable": 0, "sampleIds": ids, "orderedStops": stops, "legs": legs, "assignedWorkerIds": assigned, "collectionAssignmentIds": collections, "nodeAssignmentIds": nodes, "laboratoryAssignmentIds": labs}
	if parent.Valid {
		m["parentJourneyId"] = parent.String
	}
	if est.Valid {
		m["estimatedDeliveryAt"] = timeText(est.Time)
	}
	if len(collections) > 0 {
		m["collectionAssignmentId"] = collections[0]
	}
	trans := []string{}
	for _, l := range legs {
		var kind string
		_ = a.db.QueryRowContext(ctx, `SELECT kind FROM lablogix.assignments WHERE id=$1`, l["assignmentId"]).Scan(&kind)
		if kind == "transport" {
			trans = append(trans, l["assignmentId"].(string))
		}
	}
	if len(trans) > 0 {
		m["firstTransportAssignmentId"] = trans[0]
		m["finalTransportAssignmentId"] = trans[len(trans)-1]
	}
	if len(trans) > 2 {
		m["middleTransportAssignmentId"] = trans[1]
	}
	return m, nil
}

func (a *App) cancelJourney(w http.ResponseWriter, r *http.Request, s *Session) {
	if !requireRole(w, s, "administrator", "dispatcher") {
		return
	}
	var in struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := decode(r, &in); err != nil {
		handleErr(w, err)
		return
	}
	if in.IdempotencyKey == "" {
		fail(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	ids := []string{}
	err := a.transaction(r.Context(), func(tx *sql.Tx) error {
		var version int
		var active bool
		if e := tx.QueryRowContext(r.Context(), `SELECT plan_version,active FROM lablogix.journeys WHERE id=$1 FOR UPDATE`, in.JourneyID).Scan(&version, &active); e != nil {
			return e
		}
		if !active {
			return asError("inactive_plan", "journey plan is inactive", 409)
		}
		if version != in.ExpectedPlanVersion {
			return asError("stale_plan", "plan version has changed", 409)
		}
		rows, e := tx.QueryContext(r.Context(), `SELECT sample_id FROM lablogix.journey_samples WHERE journey_id=$1`, in.JourneyID)
		if e != nil {
			return e
		}
		for rows.Next() {
			var id string
			_ = rows.Scan(&id)
			ids = append(ids, id)
		}
		rows.Close()
		if _, e = tx.ExecContext(r.Context(), `UPDATE lablogix.journeys SET active=false,status='cancelled',plan_version=plan_version+1 WHERE id=$1`, in.JourneyID); e != nil {
			return e
		}
		if _, e = tx.ExecContext(r.Context(), `UPDATE lablogix.assignments SET status='cancelled' WHERE journey_id=$1 AND status<>'completed'`, in.JourneyID); e != nil {
			return e
		}
		if _, e = tx.ExecContext(r.Context(), `UPDATE lablogix.samples SET status='cancelled' WHERE active_journey_id=$1 AND status NOT IN('received','completed')`, in.JourneyID); e != nil {
			return e
		}
		for _, id := range ids {
			if e = releaseSample(tx, r.Context(), id); e != nil {
				return e
			}
		}
		return nil
	})
	if err == sql.ErrNoRows {
		fail(w, 404, "not_found", "journey not found")
		return
	}
	if err != nil {
		handleErr(w, err)
		return
	}
	a.audit(r.Context(), s, "cancel_journey", "journey", in.JourneyID, true, map[string]any{"reason": in.Reason, "sampleIds": ids})
	data(w, 201, map[string]any{"journeyId": in.JourneyID, "status": "cancelled", "sampleIds": ids})
}

func (a *App) rerouteJourney(w http.ResponseWriter, r *http.Request, s *Session) {
	if !requireRole(w, s, "administrator", "dispatcher") {
		return
	}
	var in struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := decode(r, &in); err != nil {
		handleErr(w, err)
		return
	}
	if in.IdempotencyKey == "" {
		fail(w, 400, "idempotency_required", "idempotencyKey is required")
		return
	}
	newID, err := a.replaceJourney(r.Context(), in.JourneyID, in.ExpectedPlanVersion)
	if err == sql.ErrNoRows {
		fail(w, 404, "not_found", "journey not found")
		return
	}
	if err != nil {
		handleErr(w, err)
		return
	}
	plan, err := a.journeyPlan(r.Context(), newID)
	if err != nil {
		handleErr(w, err)
		return
	}
	plan["replanStatus"] = "replaced"
	a.audit(r.Context(), s, "reroute_journey", "journey", in.JourneyID, true, map[string]any{"reason": in.Reason, "replacementPlanId": newID})
	data(w, 201, map[string]any{"journeyId": in.JourneyID, "replanStatus": "replaced", "replacementPlanId": newID, "replacementJourney": plan})
}
func (a *App) replaceJourney(ctx context.Context, old string, expected int) (string, error) {
	newID := uuid()
	err := a.transaction(ctx, func(tx *sql.Tx) error {
		var ver int
		var mode, status string
		var est sql.NullTime
		var cost float64
		var active bool
		if e := tx.QueryRowContext(ctx, `SELECT plan_version,route_mode,status,estimated_delivery_at,total_cost_units,active FROM lablogix.journeys WHERE id=$1 FOR UPDATE`, old).Scan(&ver, &mode, &status, &est, &cost, &active); e != nil {
			return e
		}
		if !active {
			return asError("inactive_plan", "journey is inactive", 409)
		}
		if ver != expected {
			return asError("stale_plan", "plan version has changed", 409)
		}
		if _, e := tx.ExecContext(ctx, `INSERT INTO lablogix.journeys(id,parent_journey_id,plan_version,route_mode,status,estimated_delivery_at,total_cost_units) VALUES($1,$2,$3,$4,'planned',$5,$6)`, newID, old, ver+1, mode, est, cost); e != nil {
			return e
		}
		if _, e := tx.ExecContext(ctx, `INSERT INTO lablogix.journey_samples SELECT $1,sample_id FROM lablogix.journey_samples WHERE journey_id=$2`, newID, old); e != nil {
			return e
		}
		if _, e := tx.ExecContext(ctx, `INSERT INTO lablogix.journey_stops(id,journey_id,location_id,stop_type,sequence,estimated_at,dwell_minutes,latitude,longitude,completed_at) SELECT md5(random()::text || clock_timestamp()::text)::uuid,$1,location_id,stop_type,sequence,estimated_at,dwell_minutes,latitude,longitude,completed_at FROM lablogix.journey_stops WHERE journey_id=$2`, newID, old); e != nil {
			return e
		}
		rows, e := tx.QueryContext(ctx, `SELECT sample_id,kind,sequence,from_location_id,to_location_id,node_id,laboratory_id,offered_worker_id,worker_id,status,offer_expires_at,completed_at FROM lablogix.assignments WHERE journey_id=$1 ORDER BY sequence`, old)
		if e != nil {
			return e
		}
		type assignmentClone struct {
			sampleID, kind, status                   string
			sequence                                 int
			from, to, node, lab, offered, worker     sql.NullString
			expiry, completed                        sql.NullTime
		}
		clones := []assignmentClone{}
		for rows.Next() {
			var clone assignmentClone
