		v = map[string]bool{}
	}
	return v
}
func asError(code, msg string, status int) error { return &apiError{status, code, msg} }

func (a *App) bumpNetwork(ctx context.Context) {
	_, _ = a.db.ExecContext(ctx, `UPDATE lablogix.network_meta SET revision=revision+1`)
}

func (a *App) transaction(ctx context.Context, fn func(*sql.Tx) error) error {
	tx, e := a.db.BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelSerializable})
